(function(A){Object.assign(A.D,{"G908":{"l":"βάπτισμα","o":19,"ar":"<f>*† <o>βάπτισμα</o>، <g>-τος, τό</g></f> <s><b>تغطيس</b>، <b>معمودية</b>؛ <s n=\"1.\">مجازيًا، عن الضيق والآلام: <r v=\"Mark.10.38\"></r>، <r v=\"Mark.10.39\"></r>، <r v=\"Luke.12.50\"></r>.</s> <s n=\"2.\">عن طقس المعمودية الديني؛ <s n=\"(a)\">عن معمودية يوحنا: <r v=\"Matt.3.7\"></r> <r v=\"Matt.21.25\"></r>، <r v=\"Mark.11.30\"></r>، <r v=\"Luke.7.29\"></r> <r v=\"Luke.20.4\"></r>، <r v=\"Acts.1.22\"></r> <r v=\"Acts.10.37\"></r> <r v=\"Acts.18.25\"></r> <r v=\"Acts.19.3\"></r>؛ <g>β. μετανοίας</g>، <r v=\"Mark.1.4\"></r>، <r v=\"Luke.3.3\"></r>، <r v=\"Acts.13.24\"></r> <r v=\"Acts.19.4\"></r>؛</s> <s n=\"(b)\">عن المعمودية المسيحية؛ <r v=\"Rom.6.4\"></r>، <r v=\"Eph.4.5\"></r>، <r v=\"Col.2.12\"></r>، <r v=\"1Pet.3.21\"></r>.†</s> </s> </s>","en":"<f>*† <o>βάπτισμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαπτίζω</g></x>) , prop., the result of the act, <g>τὸ βαπτίζειν</g>, as distinct from <x><g>βαπτισμός</g></x>, the act itself, </e> </et> <s><b>immersion</b>, <b>baptism</b>; <s n=\"1.\">metaph., of affliction: <r v=\"Mark.10.38\"></r>, <r v=\"Mark.10.39\"></r>, <r v=\"Luke.12.50\"></r>.</s> <s n=\"2.\">Of the religious rite of baptism; <s n=\"(a)\">of John's baptism: <r v=\"Matt.3.7\"></r> <r v=\"Matt.21.25\"></r>, <r v=\"Mark.11.30\"></r>, <r v=\"Luke.7.29\"></r> <r v=\"Luke.20.4\"></r>, <r v=\"Acts.1.22\"></r> <r v=\"Acts.10.37\"></r> <r v=\"Acts.18.25\"></r> <r v=\"Acts.19.3\"></r>; <g>β. μετανοίας</g>, <r v=\"Mark.1.4\"></r>, <r v=\"Luke.3.3\"></r>, <r v=\"Acts.13.24\"></r> <r v=\"Acts.19.4\"></r>;</s> <s n=\"(b)\">of Christian baptism; <r v=\"Rom.6.4\"></r>, <r v=\"Eph.4.5\"></r>, <r v=\"Col.2.12\"></r> (Tr., <g>-μῷ</g>, q.v.), <r v=\"1Pet.3.21\"></r> (cf. Cremer, 130; Tr., <i>Syn.</i> § xcix).†</s> </s> </s>"},"G956":{"l":"βέλος","o":1,"ar":"<f><o>βέλος</o>، <g>-εος, τό</g></f> <s><b>قذيفة</b>، <b>سهم</b>: <r v=\"Eph.6.16\"></r>.†</s>","en":"<f><o>βέλος</o>, <g>-εος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βάλλω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2671\">חֵץ</h>;]</e> </et> <s><b>a missile</b>, <b>a dart</b>: <r v=\"Eph.6.16\"></r>.†</s>"},"G991":{"l":"βλέπω","o":132,"ar":"<f><o>βλέπω</o>، </f> <s> <s n=\"1.\">عن البصر الجسدي؛ <s n=\"(a)\"><b>يُبصر، له بصر</b> (عكس <g>τυφλὸς εἶναι</g>): <r v=\"Matt.12.22\"></r>، <r v=\"John.9.7\"></r>، <r v=\"Acts.9.9\"></r>، <r v=\"Rom.11.8\"></r>، <r v=\"Rev.3.18\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\"><b>يرى، ينظر (إلى)، يُبصر</b>: مطلقًا، <r v=\"Acts.1.9\"></r>؛ مع المنصوب، <r v=\"Matt.7.3\"></r>، <r v=\"Mark.5.31\"></r>، <r v=\"Luke.6.41\"></r>، <r v=\"John.1.29\"></r>، وفي مواضع أخرى؛ <g>ὅραμα</g>، <r v=\"Acts.12.9\"></r>؛ <g>γυναῖκα</g>، <r v=\"Matt.5.28\"></r>؛ <g>βιβλίον</g>، <r v=\"Rev.5.3\"></r>، <r v=\"Rev.5.4\"></r>؛ <g>τ. βλεπόμενα</g>، <r v=\"2Cor.4.18\"></r>. </s> </s> <s n=\"2.\">مجازيًا، عن الرؤية العقلية؛ <s n=\"(a)\"><b>يرى، يدرك، يميّز</b>: مطلقًا، <r v=\"Matt.13.13\"></r>، <r v=\"Luke.8.10\"></r>؛ <g>δι’ ἐσόπτρου</g>، <r v=\"1Cor.13.12\"></r>؛ مع المنصوب، <r v=\"Heb.2.9\"></r> <r v=\"Heb.10.25\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Heb.3.19\"></r>، <r v=\"Jas.2.22\"></r>؛ </s> <s n=\"(b)\"><b>يتأمل، ينظر إلى، يحترز (ينتبه)</b>: مطلقًا، <r v=\"Mark.13.23\"></r>، <r v=\"Mark.13.33\"></r>؛ مع المنصوب، <r v=\"1Cor.1.26\"></r>، وفي مواضع أخرى؛ يليه <g>πῶς</g>، مع الإخباري، <r v=\"Luke.8.18\"></r>، <r v=\"1Cor.3.10\"></r>، <r v=\"Eph.5.15\"></r>؛ يليه <g>τί</g>، مع الإخباري، <r v=\"Mark.4.24\"></r>؛ يليه <g>εἰς πρόσωπον</g>، عن المحاباة، <r v=\"Matt.22.16\"></r>، <r v=\"Mark.12.14\"></r>. في اللغة الدارجة، <g>β. ἑαυτόν</g>: <r v=\"Mark.13.9\"></r>؛ يليه <g>ἵνα μή</g>، <r v=\"2John.1.8\"></r>؛ <g>β. ἀπό</g>، <r v=\"Mark.8.15\"></r> <r v=\"Mark.12.38\"></r>؛ يليه <g>μή</g>، مع المستقبل الإخباري، <r v=\"Col.2.8\"></r>، <r v=\"Heb.3.12\"></r>؛ وكذلك مع الماضي البسيط في صيغة الاحتمال، <r v=\"Matt.24.4\"></r>، <r v=\"Mark.13.5\"></r>. </s> </s> <s n=\"3.\">عن الموقع والاتجاه (اللاتينية <l>specto</l>)، <b>يتّجه، يُطِلّ</b> (نحو)، عن الأماكن إلخ (<r v=\"Ezek.40.23\"></r>، 24): يليه <g>κατά</g>، مع المنصوب، <r v=\"Acts.27.12\"></r> (قارن <g>ἀνα-, ἀπο-, δια-, ἐμ-, ἐπι-, περ-, προ-βλέπω</g>).</s> </s>","en":"<f><o>βλέπω</o>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7200\">ראה</h>, also for <h n=\"H6437\">פּנה</h>, etc. ;]</e> </et> <s> <s n=\"1.\">of bodily sight; <s n=\"(a)\"><b>to see, have sight</b> (opp. to <g>τυφλὸς εἶναι</g>): <r v=\"Matt.12.22\"></r>, <r v=\"John.9.7\"></r>, <r v=\"Acts.9.9\"></r>, <r v=\"Rom.11.8\"></r>, <r v=\"Rev.3.18\"></r>, al.; </s> <s n=\"(b)\"><b>to perceive, look (at), see</b>: absol., <r v=\"Acts.1.9\"></r>; c. acc., <r v=\"Matt.7.3\"></r>, <r v=\"Mark.5.31\"></r>, <r v=\"Luke.6.41\"></r>, <r v=\"John.1.29\"></r>, al.; <g>ὅραμα</g>, <r v=\"Acts.12.9\"></r>; <g>γυναῖκα</g>, <r v=\"Matt.5.28\"></r>; <g>βιβλίον</g>, <r v=\"Rev.5.3\"></r>, <r v=\"Rev.5.4\"></r>; <g>τ. βλεπόμενα</g>, <r v=\"2Cor.4.18\"></r>. </s> </s> <s n=\"2.\">Metaph., of mental vision; <s n=\"(a)\"><b>to see, perceive, discern</b>: absol., <r v=\"Matt.13.13\"></r>, <r v=\"Luke.8.10\"></r>; <g>δι’ ἐσόπτρου</g>, <r v=\"1Cor.13.12\"></r>; c. acc., <r v=\"Heb.2.9\"></r> <r v=\"Heb.10.25\"></r>; seq. <g>ὅτι</g>, <r v=\"Heb.3.19\"></r>, <r v=\"Jas.2.22\"></r>; </s> <s n=\"(b)\"><b>to consider, look to, take heed</b>: absol., <r v=\"Mark.13.23\"></r>, <r v=\"Mark.13.33\"></r>; c. acc., <r v=\"1Cor.1.26\"></r>, al.; seq. <g>πῶς</g>, c. indic., <r v=\"Luke.8.18\"></r>, <r v=\"1Cor.3.10\"></r>, <r v=\"Eph.5.15\"></r>; seq. <g>τί</g>, c. indic., <r v=\"Mark.4.24\"></r>; seq. <g>εἰς πρόσωπον</g>, of partiality, <r v=\"Matt.22.16\"></r>, <r v=\"Mark.12.14\"></r>. Colloq. (for ex. from <g>π.</g>, V. Deiss., <i>LAE</i>, 122; M, <i>Pr.</i>, 107; MM, <i>Exp.</i>, x; Milligan, <i>NTD</i>, 50), <g>β. ἑαυτόν</g>: <r v=\"Mark.13.9\"></r>; seq. <g>ἵνα μή</g>, <r v=\"2John.1.8\"></r>; <g>β. ἀπό</g>, <r v=\"Mark.8.15\"></r> <r v=\"Mark.12.38\"></r>; seq. <g>μή</g> (cl. <g>ὁρᾶν</g>), c. fut. indic., <r v=\"Col.2.8\"></r>, <r v=\"Heb.3.12\"></r>; id. c. aor. subj., <r v=\"Matt.24.4\"></r>, <r v=\"Mark.13.5\"></r>. </s> </s> <s n=\"3.\">Of situation and direction (Lat. <l>specto</l>), <b>to look, face</b> (towards), places, etc. (seq. <g>πρός</g>, Xen, <i>Hell.</i>, vii, 1, 17; <r v=\"Ezek.40.23\"></r>, 24): seq. <g>κατά</g>, c. acc., <r v=\"Acts.27.12\"></r> (cf. <g>ἀνα-, ἀπο-, δια-, ἐμ-, ἐπι-, περ-, προ-βλέπω</g>), v. <i>DCG</i>, i, 446; ii, 596.</s> </s>"},"G932":{"l":"βασιλεία","o":162,"ar":"<f><o>βασιλεία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">أصلاً بمعنى مجرد، <b>سيادة</b>، <b>سلطان ملكي</b>، <b>مُلك</b>: <r v=\"Luke.1.33\"></r> <r v=\"Luke.22.29\"></r>، <r v=\"John.18.36\"></r>، <r v=\"Acts.1.6\"></r>، <r v=\"Heb.1.8\"></r>، <r v=\"1Cor.15.24\"></r>؛ <g>λαβεῖν β.</g>، <r v=\"Luke.19.12\"></r>، <r v=\"Luke.19.15\"></r>، <r v=\"Rev.17.12\"></r>؛ <g>δοῦναι τὴν</g>، <r v=\"Rev.17.17\"></r>؛ <g>ἔχειν β.</g>، <r v=\"Rev.17.18\"></r>؛ <g>ἔρχεσθαι ἐν τ.</g> (<g>εἰς τὴν</g>) <g>β.</g>، <r v=\"Matt.16.28\"></r>، <r v=\"Luke.23.42\"></r>؛ <g>β. τ. θεοῦ</g>، <r v=\"Rev.12.10\"></r>.</s> <s n=\"2.\">كنايةً، بمعنى محسوس، <s n=\"(a)\"><b>مملكة</b>، أي الأرض أو الشعب الذي يملك عليه الملك (<r v=\"Esth.5.3\"></r>، وفي مواضع أخرى): <r v=\"Matt.4.8\"></r> <r v=\"Matt.12.25\"></r>، <r v=\"Matt.12.26\"></r> <r v=\"Matt.24.7\"></r>، <r v=\"Mark.3.24\"></r> <r v=\"Mark.6.23\"></r>، <r v=\"Luke.4.5\"></r>، <r v=\"Heb.11.33\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\"><b>الجلالة الملكية</b> (قارن تعبيرنا <i>جلالة الملك</i>)، <b>الملك</b> نفسه (<g>τ. σπέρμα τῆς β.</g>، <r v=\"2Kgs.11.1\"></r>).</s> </s> <s n=\"3.\">في السبعينية (<r v=\"Wis.6.5\"></r>، <r v=\"Tob.13.1\"></r>، وفي مواضع أخرى) والترجوم والعهد الجديد، عن حكم المسيا وملكوته، <g>ἡ β. τ. θεοῦ</g>، <g>τ. οὐρανῶν</g> (العبرية <h n=\"H4438,H8064\">מַלְכוּת שָׁמַיִם</h>، الآرامية <h n=\"H4437,H8065\">מַלְכוּתָא דִשׁמַיָּא</h>)، <b>ملكوت الله</b>؛ <g>τ. θεοῦ</g>، <r v=\"Matt.6.33\"></r> <r v=\"Matt.12.28\"></r>، وفي مواضع أخرى؛ <g>τ. οὐρανῶν</g>، <r v=\"Matt.3.2\"></r> <r v=\"Matt.4.17\"></r>، وفي مواضع أخرى؛ <g>τ. Χριστοῦ</g> (<h n=\"H4437\">מַלִכוּת דִמְשִׁיחא</h>، ترجوم يوناثان على <r v=\"Isa.53.10\"></r>)، <r v=\"Eph.5.5\"></r>؛ <g>τ. κυρίου</g>، <r v=\"2Pet.1.11\"></r>، <r v=\"Rev.11.15\"></r>؛ <g>τ. Δαυείδ</g>، <r v=\"Mark.11.10\"></r>؛ مطلقًا، <g>ἡ β.</g>، <r v=\"Matt.4.23\"></r>، <r v=\"Jas.2.5\"></r>، وفي مواضع أخرى. ويُنظَر إلى الملكوت على أنه حاضر: <r v=\"Matt.11.12\"></r>، <r v=\"Luke.17.21\"></r>، <r v=\"Rom.14.17\"></r>، وفي مواضع أخرى؛ وعلى أنه ما سيكتمل في المستقبل، <r v=\"Matt.6.10\"></r>، <r v=\"Mark.9.1\"></r>، <r v=\"John.3.5\"></r>، <r v=\"2Pet.1.11\"></r>، وفي مواضع أخرى. ومن التعبيرات الجديرة بالملاحظة: <g>ζητεῖν τὴν β.</g>، <r v=\"Matt.6.33\"></r>؛ <g>δέχεσθαι</g>، <r v=\"Mark.10.15\"></r>؛ <g>κλρονομεῖν</g>، <r v=\"Matt.25.34\"></r>؛ <g>διδόναι</g>، <r v=\"Luke.12.32\"></r>؛ <g>παραλαμβάνειν</g>، <r v=\"Heb.12.28\"></r>؛ <g>αὐτῶν</g> (<g>τοιούτων</g>) <g>ἐστὶν ἡ β.</g>، <r v=\"Matt.5.3\"></r>، <r v=\"Matt.5.10\"></r> <r v=\"Matt.19.14\"></r>، <r v=\"Mark.10.14\"></r>، <r v=\"Luke.18.16\"></r>؛ <g>διὰ τὴν β.</g>، <r v=\"Matt.19.12\"></r>؛ <g>ἕνεκεν τῆς β.</g>، <r v=\"Luke.18.29\"></r>؛ <g>εὐαγγελίζεσθαι</g>، <g>κηρύσσειν</g>، <g>διαγγέλλειν τὴν β.</g>، <r v=\"Luke.4.43\"></r> <r v=\"Luke.9.2\"></r>، <r v=\"Luke.9.60\"></r>؛ <g>ἤγγικεν ἡ β.</g>، <r v=\"Matt.3.2\"></r>، <r v=\"Mark.1.15\"></r>؛ <g>κλεῖς τῆς β.</g>، <r v=\"Matt.16.19\"></r>؛ <g>κλείειν τὴν β.</g>، <r v=\"Matt.23.14\"></r>؛ <g>υἱοὶ τῆς β.</g>، <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.38\"></r> .</s>","en":"<f><o>βασιλεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βασιλεύω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4467,H4438\">מַמְלָכָה מַלְכוּת</h>;]</e> </et> <s n=\"1.\">prop. abstract, <b>sovereignty</b>, <b>royal power</b>, <b>dominion</b>: <r v=\"Luke.1.33\"></r> <r v=\"Luke.22.29\"></r>, <r v=\"John.18.36\"></r>, <r v=\"Acts.1.6\"></r>, <r v=\"Heb.1.8\"></r>, <r v=\"1Cor.15.24\"></r>; <g>λαβεῖν β.</g>, <r v=\"Luke.19.12\"></r>, <r v=\"Luke.19.15\"></r>, <r v=\"Rev.17.12\"></r>; <g>δοῦναι τὴν</g>, <r v=\"Rev.17.17\"></r>; <g>ἔχειν β.</g>, <r v=\"Rev.17.18\"></r>; <g>ἔρχεσθαι ἐν τ.</g> (<g>εἰς τὴν</g>) <g>β.</g>, <r v=\"Matt.16.28\"></r>, <r v=\"Luke.23.42\"></r>; <g>β. τ. θεοῦ</g>, <r v=\"Rev.12.10\"></r>.</s> <s n=\"2.\">By meton., concrete (MM, <i>Exp.</i>, x), <s n=\"(a)\"><b>a kingdom</b>, the territory or people over whom the king rules (<r v=\"Esth.5.3\"></r>, al.): <r v=\"Matt.4.8\"></r> <r v=\"Matt.12.25\"></r>, <r v=\"Matt.12.26\"></r> <r v=\"Matt.24.7\"></r>, <r v=\"Mark.3.24\"></r> <r v=\"Mark.6.23\"></r>, <r v=\"Luke.4.5\"></r>, <r v=\"Heb.11.33\"></r>, al.;</s> <s n=\"(b)\"><b>the royal majesty</b> (cf. our phrase <i>His Majesty</i>), <b>the king</b> himself (<g>τ. σπέρμα τῆς β.</g>, <r v=\"2Kgs.11.1\"></r>).</s> </s> <s n=\"3.\">In LXX (<r v=\"Wis.6.5\"></r>, <r v=\"Tob.13.1\"></r>, al.), Targ. and NT, of the Messianic rule and kingdom, <g>ἡ β. τ. θεοῦ</g>, <g>τ. οὐρανῶν</g> (Heb. <h n=\"H4438,H8064\">מַלְכוּת שָׁמַיִם</h>, Aram. <h n=\"H4437,H8065\">מַלְכוּתָא דִשׁמַיָּא</h>; v. Dalman, <i>Words</i>, 91-147; Cremer, 132, 658), <b>the kingdom of God</b> (on the equivalence of the two phrases, v. Dalman, <i>op. cit.</i>, 93, 218 f.); <g>τ. θεοῦ</g>, <r v=\"Matt.6.33\"></r> <r v=\"Matt.12.28\"></r>, al.; <g>τ. οὐρανῶν</g>, <r v=\"Matt.3.2\"></r> <r v=\"Matt.4.17\"></r>, al.; <g>τ. Χριστοῦ</g> (<h n=\"H4437\">מַלִכוּת דִמְשִׁיחא</h>, Targ. Jon. on <r v=\"Isa.53.10\"></r>), <r v=\"Eph.5.5\"></r>; <g>τ. κυρίου</g>, <r v=\"2Pet.1.11\"></r>, <r v=\"Rev.11.15\"></r>; <g>τ. Δαυείδ</g>, <r v=\"Mark.11.10\"></r>; absol., <g>ἡ β.</g>, <r v=\"Matt.4.23\"></r>, <r v=\"Jas.2.5\"></r>, al. The kingdom is regarded as present: <r v=\"Matt.11.12\"></r>, <r v=\"Luke.17.21\"></r>, <r v=\"Rom.14.17\"></r>, al.; as that which is to be consummated in the future, <r v=\"Matt.6.10\"></r>, <r v=\"Mark.9.1\"></r>, <r v=\"John.3.5\"></r>, <r v=\"2Pet.1.11\"></r>, al. Noteworthy phrases are: <g>ζητεῖν τὴν β.</g>, <r v=\"Matt.6.33\"></r>; <g>δέχεσθαι</g>, <r v=\"Mark.10.15\"></r>; <g>κλρονομεῖν</g>, <r v=\"Matt.25.34\"></r>; <g>διδόναι</g>, <r v=\"Luke.12.32\"></r>; <g>παραλαμβάνειν</g>, <r v=\"Heb.12.28\"></r>; <g>αὐτῶν</g> (<g>τοιούτων</g>) <g>ἐστὶν ἡ β.</g>, <r v=\"Matt.5.3\"></r>, <r v=\"Matt.5.10\"></r> <r v=\"Matt.19.14\"></r>, <r v=\"Mark.10.14\"></r>, <r v=\"Luke.18.16\"></r>; <g>διὰ τὴν β.</g>, <r v=\"Matt.19.12\"></r>; <g>ἕνεκεν τῆς β.</g>, <r v=\"Luke.18.29\"></r>; <g>εὐαγγελίζεσθαι</g>, <g>κηρύσσειν</g>, <g>διαγγέλλειν τὴν β.</g>, <r v=\"Luke.4.43\"></r> <r v=\"Luke.9.2\"></r>, <r v=\"Luke.9.60\"></r>; <g>ἤγγικεν ἡ β.</g>, <r v=\"Matt.3.2\"></r>, <r v=\"Mark.1.15\"></r>; <g>κλεῖς τῆς β.</g>, <r v=\"Matt.16.19\"></r>; <g>κλείειν τὴν β.</g>, <r v=\"Matt.23.14\"></r>; <g>υἱοὶ τῆς β.</g>, <r v=\"Matt.8.12\"></r> <r v=\"Matt.13.38\"></r> (cf. Cremer, 132, 658).</s>"},"G988":{"l":"βλασφημία","o":18,"ar":"<f><o>βλασφημία</o>، <g>-ας, ἡ</g> </f> <s n=\"(a)\"><b>افتراء وشتيمة</b>: <r v=\"Matt.12.31\"></r> <r v=\"Matt.15.19\"></r>، <r v=\"Mark.3.28\"></r> <r v=\"Mark.7.22\"></r>، <r v=\"Eph.4.31\"></r>، <r v=\"Col.3.8\"></r>، <r v=\"1Tim.6.4\"></r>، <r v=\"Jude.1.9\"></r>، <r v=\"Rev.2.9\"></r>؛ </s> <s n=\"(b)\">خاصةً، <b>كلام شرير في حق الله، تجديف</b>: <r v=\"Matt.26.65\"></r>، <r v=\"Mark.14.64\"></r>، <r v=\"Luke.5.21\"></r>، <r v=\"John.10.33\"></r>، <r v=\"Rev.13.5\"></r>؛ <g>ὄνομα βλασφημίας</g>، <r v=\"Rev.13.1\"></r> <r v=\"Rev.17.3\"></r>؛ مع المضاف إليه المفعولي <r v=\"Matt.12.31\"></r>؛ <g>πρὸς τ. θεόν</g>، <r v=\"Rev.13.6\"></r> .†</s>","en":"<f><o>βλασφημία</o>, <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βλάσφημος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.35.12\"></r> (<h n=\"H5007\">נֶאָצָה</h>), <r v=\"Dan.3.29\"></r> (<h n=\"H7952\">שׁלה</h>), <r v=\"Tob.1.18\"></r>, <r v=\"1Macc.2.6\"></r>, <r v=\"2Macc.8.4\"></r> <r v=\"2Macc.10.35\"></r> <r v=\"2Macc.15.24\"></r> * ;]</e> </et> <s n=\"(a)\"><b>railing slander</b>: <r v=\"Matt.12.31\"></r> <r v=\"Matt.15.19\"></r>, <r v=\"Mark.3.28\"></r> <r v=\"Mark.7.22\"></r>, <r v=\"Eph.4.31\"></r>, <r v=\"Col.3.8\"></r>, <r v=\"1Tim.6.4\"></r>, <r v=\"Jude.1.9\"></r>, <r v=\"Rev.2.9\"></r>; </s> <s n=\"(b)\">spec., <b>impious speech against God, blasphemy</b>: <r v=\"Matt.26.65\"></r>, <r v=\"Mark.14.64\"></r>, <r v=\"Luke.5.21\"></r>, <r v=\"John.10.33\"></r>, <r v=\"Rev.13.5\"></r>; <g>ὄνομα βλασφημίας</g>, <r v=\"Rev.13.1\"></r> <r v=\"Rev.17.3\"></r>; c. gen. obj. <r v=\"Matt.12.31\"></r>; <g>πρὸς τ. θεόν</g>, <r v=\"Rev.13.6\"></r> (Cremer, 570; <i>DB</i>, i, 305; <i>DCG</i> ii, 423).†</s>"},"G957":{"l":"βέλτιον","o":2,"ar":"<f><o>βελτίων</o>، <g>-ον</g> (حالة الجر <g>-ονος</g>)، صيغة التفضيل من <x><g>ἀγαθός</g></x>،</f> <s>المحايد ظرفًا: <b>أفضل</b>، <b>جيدًا جدًّا</b>: <r v=\"2Tim.1.18\"></r> (قارن أيضًا <r v=\"Acts.10.28\"></r>).†</s>","en":"<f><o>βελτίων</o>, <g>-ον</g> (gen. <g>-ονος</g>), comp. of <x><g>ἀγαθός</g></x>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2896\">טוֹב</h>;]</e> </et> <s>neut. as adv., <b>better</b>, <b>very well</b>: <r v=\"2Tim.1.18\"></r> (also <r v=\"Acts.10.28\"></r> D). On <i>elative</i> use in these passages, v. M, <i>Pr.</i>, 78, 236.†</s>"},"G948":{"l":"βδελύσσω","o":2,"ar":"<f><o>βδελύσσω</o></f> <s><b>يُنجِّس، يجعله كريهًا</b>؛ المبني للمجهول، <r v=\"Rev.21.8\"></r>؛ الصيغة الوسطى: <b>ينفر باشمئزاز</b>، <b>يستكره، يمقت</b>: <r v=\"Rom.2.22\"></r>.†</s>","en":"<f><o>βδελύσσω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>βδέω</g></x>, <i>to stink</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8581\">תּעב</h>, <h n=\"H8262\">שׁקץ</h>;]</e> <e t=\"derivation\">&gt;in cl., mid. only (Attic, <g>-ττομαι</g>);</e> </et> <s><b>to make foul</b>; pass., <r v=\"Rev.21.8\"></r>; mid., <b>to turn away in disgust from</b>, <b>to detest</b>: <r v=\"Rom.2.22\"></r> (Cremer, 137).†</s>"},"G987":{"l":"βλασφημέω","o":34,"ar":"<f><o>βλασφημέω</o>، <g>-ῶ</g> </f> <s> <s n=\"1.\"><b>تكلم باستخفاف أو بتدنيس عن الأمور المقدسة</b> (عكس <g>εὐφημέω</g>)، وخاصةً <b>تكلم بكفر على الله، جدّف، نطق بالتجديف</b>: مطلقًا: <r v=\"Matt.9.3\"></r>، <r v=\"Matt.26.65\"></r>، <r v=\"Mark.2.7\"></r>، <r v=\"John.10.36\"></r>، <r v=\"Acts.26.11\"></r>، <r v=\"1Tim.1.20\"></r>، <r v=\"2Pet.2.12\"></r>؛ <g>τ. θεόν</g>: <r v=\"Acts.19.37\"></r>، <r v=\"Rev.16.11\"></r>، <r v=\"Rev.16.21\"></r>؛ <g>τὸ ὄνομα τ. θεοῦ</g>: <r v=\"Rev.13.6\"></r>، <r v=\"Rev.16.9\"></r>؛ <g>δόξας</g>: <r v=\"Jude.1.3\"></r>، <r v=\"2Pet.2.10\"></r>؛ <g>εἰς τὸ πνεῦμα τὸ πνεῦμα τὸ ἅγιον</g>: <r v=\"Mark.3.29\"></r>، <r v=\"Luke.12.10\"></r>. </s> <s n=\"2.\"><b>شتم، عيّر، افترى على</b>: مطلقًا: <r v=\"Luke.22.65\"></r>، <r v=\"Acts.13.45\"></r>، <r v=\"Acts.18.6\"></r>، <r v=\"1Pet.4.4\"></r>؛ مع المنصوب: <r v=\"Matt.27.39\"></r>، <r v=\"Mark.3.28\"></r>، <r v=\"Mark.15.29\"></r>، <r v=\"Luke.23.39\"></r>، <r v=\"Titus.3.2\"></r>، <r v=\"Jas.2.7\"></r>، <r v=\"Jude.1.10\"></r>. المبني للمجهول: <r v=\"Rom.2.24\"></r>، <r v=\"Rom.3.8\"></r>، 14:16، <r v=\"1Cor.10.30\"></r>، <r v=\"1Tim.6.1\"></r>، <r v=\"Titus.2.5\"></r>، <r v=\"2Pet.2.2\"></r>.†</s> </s>","en":"<f><o>βλασφημέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βλάσφημος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.19.4\"></r> (<h n=\"H3198\">יכח</h> hi.) <r v=\"2Kgs.19.6\"></r>, <r v=\"2Kgs.19.22\"></r> (<h n=\"H1442\">גּדף</h> pi.), <r v=\"Isa.52.5\"></r> (<h n=\"H5006\">נאץ</h> hith.), <r v=\"Dan.3.29\"></r> (<h n=\"H559,H7971\">אמר שׁלח</h>), <r v=\"Tob.1.18\"></r>, <r v=\"Bel.1.9\"></r>, <r v=\"2Macc.1.2\"></r> * ;]</e> </et> <s> <s n=\"1.\"><b>to speak lightly or profanely of sacred things</b> (in cl., opp. of <g>εὐφημέω</g>), esp. <b>to speak impiously of God, to blaspheme, speak blasphemously</b>: absol., <r v=\"Matt.9.3\"></r> <r v=\"Matt.26.65\"></r>, <r v=\"Mark.2.7\"></r>, <r v=\"John.10.36\"></r>, <r v=\"Acts.26.11\"></r>, <r v=\"1Tim.1.20\"></r>, <r v=\"2Pet.2.12\"></r>; <g>τ. θεόν</g>, <r v=\"Acts.19.37\"></r>, <r v=\"Rev.16.11\"></r>, <r v=\"Rev.16.21\"></r>; <g>τὸ ὄνομα τ. θεοῦ</g>, <r v=\"Rev.13.6\"></r> <r v=\"Rev.16.9\"></r>; <g>δόξας</g>, <r v=\"Jude.1.3\"></r>, <r v=\"2Pet.2.10\"></r>; <g>εἰς τὸ πνεῦμα τὸ πνεῦμα τὸ ἅγιον</g>, <r v=\"Mark.3.29\"></r>, <r v=\"Luke.12.10\"></r>. </s> <s n=\"2.\"><b>to revile, rail at, slander</b>: absol., <r v=\"Luke.22.65\"></r>, <r v=\"Acts.13.45\"></r> <r v=\"Acts.18.6\"></r>, <r v=\"1Pet.4.4\"></r>; c. acc., <r v=\"Matt.27.39\"></r>, <r v=\"Mark.3.28\"></r> <r v=\"Mark.15.29\"></r>, <r v=\"Luke.23.39\"></r>, <r v=\"Titus.3.2\"></r>, <r v=\"Jas.2.7\"></r>, <r v=\"Jude.1.10\"></r>. Pass.: <r v=\"Rom.2.24\"></r> <r v=\"Rom.3.8\"></r> 14:16, <r v=\"1Cor.10.30\"></r>, <r v=\"1Tim.6.1\"></r>, <r v=\"Titus.2.5\"></r>, <r v=\"2Pet.2.2\"></r> (Cremer, 570).†</s> </s>"},"G958":{"l":"Βενιαμίν","o":4,"ar":"<f><o>Βενιαμίν</o>، <g>ὁ</g>، لا يُصرَّف</f> <s><b>بنيامين</b>: <r v=\"Acts.13.21\"></r>، <r v=\"Rom.11.1\"></r>، <r v=\"Phil.3.5\"></r>، <r v=\"Rev.7.8\"></r>.†</s>","en":"<f><o>Βενιαμίν</o>, (Rec. <g>-μίν</g>), <g>ὁ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1144\">בֶּנְיָמִין</h>),</e> </et> <s><b>Benjamin</b>: <r v=\"Acts.13.21\"></r>, <r v=\"Rom.11.1\"></r>, <r v=\"Phil.3.5\"></r>, <r v=\"Rev.7.8\"></r>.†</s>"},"G994":{"l":"βοάω","o":12,"ar":"<f><o>βοάω</o>، <g>-ῶ</g> </f> <s> <s n=\"1.\">مطلقًا: <b>صرخ، نادى</b>: <r v=\"Matt.3.3\"></r>، <r v=\"Matt.27.46\"></r>، <r v=\"Mark.1.3\"></r> <r v=\"Mark.15.34\"></r>، <r v=\"Luke.3.4\"></r> <r v=\"Luke.9.38\"></r> <r v=\"Luke.18.38\"></r>، <r v=\"John.1.23\"></r>، <r v=\"Acts.8.7\"></r> <r v=\"Acts.17.6\"></r> <r v=\"Acts.25.24\"></r>، <r v=\"Gal.4.27\"></r>. </s> <s n=\"2.\">مع القابل: <b>استغاث بـ</b>، صرخ طالبًا العون (العبرية <h n=\"H2199,H5921\">זעק על</h>، <r v=\"Hos.7.14\"></r>، وفي مواضع أخرى)، <r v=\"Luke.18.7\"></r>.† </s> </s>","en":"<f><o>βοάω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βοή</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2199\">זעק</h>, <h n=\"H6817\">צעק</h>, <h n=\"H7121\">קרא</h> ;]</e> </et> <s> <s n=\"1.\">absol., <b>to cry, call out</b>: <r v=\"Matt.3.3\"></r>, <r v=\"Matt.27.46\"></r>, <r v=\"Mark.1.3\"></r> <r v=\"Mark.15.34\"></r>, <r v=\"Luke.3.4\"></r> <r v=\"Luke.9.38\"></r> <r v=\"Luke.18.38\"></r>, <r v=\"John.1.23\"></r>, <r v=\"Acts.8.7\"></r> <r v=\"Acts.17.6\"></r> <r v=\"Acts.25.24\"></r>, <r v=\"Gal.4.27\"></r>. </s> <s n=\"2.\">C. dat., <b>to call on</b> for help (Heb. <h n=\"H2199,H5921\">זעק על</h>, <r v=\"Hos.7.14\"></r>, al.), <r v=\"Luke.18.7\"></r>.† </s> </s> <sy><i>SYN.</i>: <g>καλέω</g>, <i>to call, invite, summon</i>; <g>κράζω</g>, <i>to cry</i>, harshly or inarticulately, as animals; <g>κραυγάζω</g>, intensive of <g>κράζω</g>. <g>βοάω</g> expresses emotion, whether joy, fear, etc.</sy>"},"G940":{"l":"βασκαίνω","o":1,"ar":"<f><o>βασκαίνω</o>،</f> <s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>افترى، ذمّ</b>.</s> <s n=\"2.\"><b>أصاب بالعين الشريرة، حسد</b>، <b>فتن</b>، <b>سحر، رقى</b>: <r v=\"Gal.3.1\"></r>.†</s> </s>","en":"<f><o>βασκαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.28.54\"></r>, <r v=\"Deut.28.56\"></r> (<h n=\"H7489\">רעע</h>), <r v=\"Sir.14.6\"></r>, <r v=\"Sir.14.8\"></r>*;]</e> </et> <s> <s n=\"1.\"><b>to slander</b> (Dem.).</s> <s n=\"2.\"><b>to blight by the evil eye</b>, <b>to fascinate</b>, <b>bewitch</b>: <r v=\"Gal.3.1\"></r>.†</s> </s>"},"G947":{"l":"βδελυκτός","o":1,"ar":"<f>† <o>βδελυκτός</o>، <g>ή, -όν</g></f> <s><b>رجس</b>، <b>مكروه، ممقوت</b>: <r v=\"Titus.1.16\"></r>.†</s>","en":"<f>† <o>βδελυκτός</o>, <g>ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βδελύσσω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.17.15\"></r> (<h n=\"H8441\">תּוֹעֵבָה</h>), <r v=\"Sir.41.5\"></r>, <r v=\"2Macc.1.27\"></r>*;]</e> </et> <s><b>abominable</b>, <b>detestable</b>: <r v=\"Titus.1.16\"></r> (Cremer, 137).†</s>"},"G949":{"l":"βέβαιος","o":8,"ar":"<f>** <o>βέβαιος</o>، <g>-ον</g> (وأيضًا <g>-α, -ον</g>؛</f> <s><b>ثابت</b>، <b>راسخ</b>: <g>ἄγκυρα</g>، <r v=\"Heb.6.19\"></r>؛ مجازيًا، <b>أكيد، مضمون</b> (خاصةً بمعنى الضمان القانوني): <g>ἐπαγγελία</g>، <r v=\"Rom.4.16\"></r>؛ <g>ἐλπίς</g>، <r v=\"2Cor.1.6\"></r>؛ <g>λόγος</g>، <r v=\"Heb.2.2\"></r>؛ <g>παρρησία</g>، <r v=\"Heb.3.6\"></r>؛ <g>ἀρχή</g> (<g>τ. ὑποστάσεως</g>)، <r v=\"Heb.3.14\"></r>؛ <g>διαθήκη</g>، <r v=\"Heb.9.17\"></r>؛ <g>κλῆσις κ. ἐκλογή</g>، <r v=\"2Pet.1.10\"></r>؛ صيغة التفضيل (<g>-ότερος</g>)، <g>προφητικὸς λόγος</g>، <r v=\"2Pet.1.19\"></r>.†</s>","en":"<f>** <o>βέβαιος</o>, <g>-ον</g> (also <g>-α, -ον</g>;</f> <et> <e t=\"derivation\">&lt; <x><g>βαίνω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Esth.3.13\"></r>, <r v=\"Wis.7.23\"></r>, <r v=\"3Macc.5.31\"></r> <r v=\"3Macc.7.7\"></r>, <r v=\"4Macc.17.4\"></r>*;]</e> </et> <s><b>firm</b>, <b>secure</b>: <g>ἄγκυρα</g>, <r v=\"Heb.6.19\"></r>; metaph., <b>sure</b> (esp. \"in the sense of legally guaranteed security,\" Deiss., <i>BS</i>, 109; cf . two foll. words): <g>ἐπαγγελία</g>, <r v=\"Rom.4.16\"></r>; <g>ἐλπίς</g>, <r v=\"2Cor.1.6\"></r>; <g>λόγος</g>, <r v=\"Heb.2.2\"></r>; <g>παρρησία</g>, <r v=\"Heb.3.6\"></r>; <g>ἀρχή</g> (<g>τ. ὑποστάσεως</g>), <r v=\"Heb.3.14\"></r>; <g>διαθήκη</g>, <r v=\"Heb.9.17\"></r>; <g>κλῆσις κ. ἐκλογή</g>, <r v=\"2Pet.1.10\"></r>; comp. (<g>-ότερος</g>), <g>προφητικὸς λόγος</g>, <r v=\"2Pet.1.19\"></r>.†</s>"},"G936":{"l":"βασιλεύω","o":21,"ar":"<f><o>βασιλεύω</o>،</f> <s><b>يكون ملكًا</b>، <b>يملك</b>، <b>يحكم</b>: <r v=\"1Tim.6.15\"></r>؛ مع المضاف إليه، <r v=\"Matt.2.22\"></r>؛ يليه <g>ἐπί</g> مع المنصوب (= العبرية <h n=\"H3427,H5921\">מלךְ על</h>)، <r v=\"Luke.1.33\"></r> <r v=\"Luke.19.14\"></r>، <r v=\"Luke.19.27\"></r>، <r v=\"Rom.5.14\"></r>؛ <g>ἐπὶ τ. γῆς</g>، <b>على الأرض</b>، <r v=\"Rev.5.10\"></r>؛ عن الله، <r v=\"Rev.11.15\"></r>، <r v=\"Rev.11.17\"></r> <r v=\"Rev.19.6\"></r>؛ عن المسيح، <r v=\"Luke.1.33\"></r>، <r v=\"1Cor.15.25\"></r>، <r v=\"Rev.11.15\"></r>؛ عن المسيحيين، <r v=\"Rev.5.10\"></r> <r v=\"Rev.20.4\"></r>، <r v=\"Rev.20.6\"></r> <r v=\"Rev.22.5\"></r>. مجازيًا: المسيحيون، <r v=\"Rom.5.17\"></r>، <r v=\"1Cor.4.8\"></r>؛ <g>θάνατος</g> (الموت)، <r v=\"Rom.5.14\"></r>، <r v=\"Rom.5.17\"></r>؛ <g>ἁμαρτία</g> (الخطية)، <r v=\"Rom.5.21\"></r> <r v=\"Rom.6.12\"></r>. الماضي البسيط بمعنى الابتداء: <b>يبدأ يملك، يتولى المُلك</b>: <r v=\"1Cor.4.8\"></r>، <r v=\"Rev.11.17\"></r> <r v=\"Rev.19.6\"></r>.†</s>","en":"<f><o>βασιλεύω</o>,</f> <et> <e t=\"derivation\">(&lt; <x><g>βασιλεύς</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4427\">מלךְ</h>, its parts and derivatives, exc. <r v=\"2Kgs.15.5\"></r> (<h n=\"H3427\">ישׁב</h>);]</e> </et> <s><b>to be king</b>, <b>to reign</b>, <b>rule</b>: <r v=\"1Tim.6.15\"></r>; c. gen. (cl.), <r v=\"Matt.2.22\"></r>; seq. <g>ἐπί</g>, c. acc. (= Heb. <h n=\"H3427,H5921\">מלךְ על</h>; Bl., § 36, 8), <r v=\"Luke.1.33\"></r> <r v=\"Luke.19.14\"></r>, <r v=\"Luke.19.27\"></r>, <r v=\"Rom.5.14\"></r>; <g>ἐπὶ τ. γῆς</g>, <b>on earth</b>, <r v=\"Rev.5.10\"></r>; of God, <r v=\"Rev.11.15\"></r>, <r v=\"Rev.11.17\"></r> <r v=\"Rev.19.6\"></r>; of Christ, <r v=\"Luke.1.33\"></r>, <r v=\"1Cor.15.25\"></r>, <r v=\"Rev.11.15\"></r>; of Christians, <r v=\"Rev.5.10\"></r> <r v=\"Rev.20.4\"></r> (constative aor., M, <i>Pr.</i>, 130), <r v=\"Rev.20.6\"></r> <r v=\"Rev.22.5\"></r>. Metaph., Christians, <r v=\"Rom.5.17\"></r>, <r v=\"1Cor.4.8\"></r>; <g>θάνατος</g>, <r v=\"Rom.5.14\"></r>, <r v=\"Rom.5.17\"></r>; <g>ἁμαρτία</g>, <r v=\"Rom.5.21\"></r> <r v=\"Rom.6.12\"></r>. Ingressive aor. (M, <i>Pr.</i>, 109), <b>to begin to reign</b>: <r v=\"1Cor.4.8\"></r>, <r v=\"Rev.11.17\"></r> <r v=\"Rev.19.6\"></r> (Cremer, 137).†</s>"},"G915":{"l":"βάρβαρος","o":6,"ar":"<f><o>βάρβαρος</o>، <g>-ον</g></f> <s><b>بربري</b>، <b>أعجمي</b>، غريب عن اللغة اليونانية وثقافتها (واكتسب أيضًا بعد الحرب الفارسية معنى <b>وحشي</b>، <b>فظّ</b>): <r v=\"Acts.28.2\"></r>، <r v=\"Acts.28.4\"></r>، <r v=\"Rom.1.14\"></r>، <r v=\"1Cor.14.11\"></r>، <r v=\"Col.3.11\"></r>.†</s>","en":"<f><o>βάρβαρος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(prob. onomatop., descriptive of unintelligible sounds),</e> <e t=\"septuagint\">[in LXX: <r v=\"LXX:Ps.114.1\"></r> (<h n=\"H3937\">לעז</h>), <r v=\"Ezek.21.31\"></r> (<r v=\"Ezek.21.36\"></r>) (<h n=\"H1197\">בּער</h>), <r v=\"2Macc.2.21\"></r> <r v=\"2Macc.4.25\"></r> <r v=\"2Macc.10.4\"></r>, <r v=\"3Macc.3.24\"></r>*;]</e> </et> <s><b>barbarous</b>, <b>barbarian</b>, strange to Greek language and culture (and also, after the Persian war, with the added sense of <b>brutal</b>, <b>rude</b>): <r v=\"Acts.28.2\"></r>, <r v=\"Acts.28.4\"></r>, <r v=\"Rom.1.14\"></r>, <r v=\"1Cor.14.11\"></r>, <r v=\"Col.3.11\"></r> (v. Lft., in l., and <i>Notes</i>, 249).†</s>"},"G921":{"l":"Βαρναβᾶς","o":28,"ar":"<f><o>Βαρ-ναβᾶς</o>، <g>-α, ὁ</g></f> <s><b>برنابا</b>: <r v=\"Acts.4.36\"></r> <r v=\"Acts.9.27\"></r> <r v=\"Acts.11.22\"></r>، <r v=\"Acts.11.30\"></r> <r v=\"Acts.12.25\"></r> <r v=\"Acts.13.1-Acts.15.41\"></r>، <r v=\"1Cor.9.6\"></r>، <r v=\"Gal.2.1\"></r>، <r v=\"Gal.2.9\"></r>، <r v=\"Gal.2.13\"></r>، <r v=\"Col.4.10\"></r>.†</s>","en":"<f><o>Βαρ-ναβᾶς</o>, <g>-α, ὁ</g></f> <et> <e t=\"derivation\">(Aram. <h n=\"H1247\">בַּר</h>, <i>son</i>, as prefix to another word interpreted in <r v=\"Acts.4.36\"></r>, <g>τῆς παρακλήσεως</g>, perh. <h n=\"H5017\">נְבוּאָה</h>, wh., however, should be rendered by <g>προφητεία</g> as in <r v=\"2Esd.6.14\"></r>, LXX. Deiss., <i>BS</i>, 309 f., thinks <g>Β.</g> may be a variant of the name <g>Βαρνεβοῦς</g>, <i>son of Nebo</i>, found in a Syrian Inscr., altered with a view to disguising its origin; v. also Milligan, <i>NTD</i>, iii; Dalman, <i>Gr.</i>, 142),</e> </et> <s><b>Barnabas</b>: <r v=\"Acts.4.36\"></r> <r v=\"Acts.9.27\"></r> <r v=\"Acts.11.22\"></r>, <r v=\"Acts.11.30\"></r> <r v=\"Acts.12.25\"></r> <r v=\"Acts.13.1-Acts.15.41\"></r>, <r v=\"1Cor.9.6\"></r>, <r v=\"Gal.2.1\"></r>, <r v=\"Gal.2.9\"></r>, <r v=\"Gal.2.13\"></r>, <r v=\"Col.4.10\"></r>.†</s>"},"G922":{"l":"βάρος","o":6,"ar":"<f><o>βάρος</o>، <g>-εος, τό</g>،</f> <s><b>ثِقل</b>؛ <s n=\"(a)\"><b>ثِقل</b>، <b>حِمل</b>، حرفيًا ومجازيًا: <r v=\"Matt.20.12\"></r>، <r v=\"Acts.15.28\"></r>، <r v=\"2Cor.4.17\"></r>، <r v=\"Rev.2.24\"></r>؛ <g>ἀλλήλων τὰ β.</g>: <b>أخطاء بعضكم بعضًا</b>، <r v=\"Gal.6.2\"></r>؛ <g>ἐν β.</g>: <b>مُثقِّلين</b>: <r v=\"1Thess.2.6\"></r>، بحسب متن الترجمة المنقحة، ولكن انظر أدناه؛</s> <s n=\"(b)\">في اليونانية المتأخرة: <b>وقار، هيبة</b>، <b>سلطة</b>: <g>ἐν βάρει</g>، <r v=\"1Thess.2.6\"></r> (بحسب هامش الترجمة المنقحة).†</s> </s>","en":"<f><o>βάρος</o>, <g>-εος, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.18.21\"></r> (<h n=\"H3527\">כּבד</h>), <r v=\"Jdt.7.4\"></r>, <r v=\"Sir.13.2\"></r>, <r v=\"2Macc.9.10\"></r>, <r v=\"3Macc.5.47\"></r>*;]</e> </et> <s><b>weight</b>; <s n=\"(a)\"><b>a weight</b>, <b>burden</b>, lit. and metaph.: <r v=\"Matt.20.12\"></r>, <r v=\"Acts.15.28\"></r>, <r v=\"2Cor.4.17\"></r>, <r v=\"Rev.2.24\"></r>; <g>ἀλλήλων τὰ β.</g>, <b>one another's faults</b>, <r v=\"Gal.6.2\"></r>; <g>ἐν β.</g>, <b>burdensome</b>: <r v=\"1Thess.2.6\"></r>, R, txt., but v. infr.;</s> <s n=\"(b)\">in late Gk. (Soph., <i>Lex.</i>, s.v.), <b>dignity</b>, <b>authority</b>: <g>ἐν βάρει</g>, <r v=\"1Thess.2.6\"></r> (R, mg.; v. Milligan, <i>ICG</i>, in l.).†</s> </s> <sy><i>SYN.</i>: <x><g>ὄγκος</g></x>, <i>an encumbrance</i>; <x><g>φορτίον</g></x>, <b>a burden</b>, that which is borne.</sy>"},"G951":{"l":"βεβαίωσις","o":2,"ar":"<f><o>βεβαίωσις</o>، <g>-εως, ἡ</g></f> <s><b>تثبيت، توكيد</b>: <g>τ. εὐαγγελίου</g>، <r v=\"Phil.1.7\"></r>؛ <g>εἰς β.</g>، <b>للتثبيت</b>، <r v=\"Heb.6.16\"></r>، وهي عبارة شائعة خارج الكتاب المقدس للدلالة على الضمان في المعاملات التجارية.†</s>","en":"<f><o>βεβαίωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βεβαιόω</g></x>, q.v.),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.25.23\"></r> (<h n=\"H6783\">צְמִיתֻת</h>), <r v=\"Wis.6.19\"></r>*;]</e> </et> <s><b>confirmation</b>: <g>τ. εὐαγγελίου</g>, <r v=\"Phil.1.7\"></r>; <g>εἰς β.</g>, <r v=\"Heb.6.16\"></r>, a phrase freq. in <g>π.</g> of guarantee in a business transaction (Deiss., <i>BS</i>, 104 ff.; Cremer, 140).†</s>"},"G982":{"l":"βιωτικός","o":3,"ar":"<f>* <o>βιωτικός</o>، <g>-ή, -όν</g> </f> <s><b>متعلّق بالحياة</b>، ومن ثمّ: <b>دنيوي، معيشي</b>: <r v=\"Luke.21.34\"></r>، <r v=\"1Cor.6.3\"></r>، <r v=\"1Cor.6.4\"></r>.†</s>","en":"<f>* <o>βιωτικός</o>, <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>βιός</g>), </e> </et> <s><b>pertaining to life</b>, hence, <b>worldly</b> (Field, <i>Notes</i>, 171): <r v=\"Luke.21.34\"></r>, <r v=\"1Cor.6.3\"></r>, <r v=\"1Cor.6.4\"></r>.†</s>"},"G907":{"l":"βαπτίζω","o":77,"ar":"<f><o>βαπτίζω</o></f> <s><b>غَمَسَ</b>، <b>غَطَّسَ</b>، <b>أغرقَ</b>؛ <s n=\"1.\">عمومًا؛ مجازيًا: <b>غَمَرَ</b> (<r v=\"Isa.21.4\"></r>)؛ مع مفعول مطلق من لفظه: <g>βάπτισμα β.</g>: <r v=\"Mark.10.38\"></r>، <r v=\"Mark.10.39\"></r>، <r v=\"Luke.12.50\"></r>. الصيغة الوسطى:</s> <s n=\"2.\"><b>اغتسل (اغتسالات طقسية)</b>، <b>غسل نفسه</b>، <b>استحمّ</b> (<r v=\"2Kgs.5.14\"></r>، <r v=\"Jdt.12.7\"></r>، <r v=\"LXX:Sir.34.30\"></r>): <r v=\"Mark.7.4\"></r>؛ والماضي البسيط المبني للمجهول بالمعنى نفسه: <r v=\"Luke.11.38\"></r>.</s> <s n=\"3\">عن الاغتسال والتغطيس كطقس ديني: <b>عَمَّدَ</b>؛ <s n=\"(a)\">مطلقًا (بلا مفعول): <r v=\"Mark.1.4\"></r>، <r v=\"John.1.25\"></r>، <r v=\"John.1.26\"></r>، <r v=\"John.1.28\"></r>، <r v=\"John.3.22\"></r>، <r v=\"John.3.23\"></r>، <r v=\"John.3.26\"></r>، <r v=\"John.4.2\"></r>، <r v=\"John.10.40\"></r>، <r v=\"1Cor.1.17\"></r>؛ <g>ὁ βαπτίζων</g> (= <g>ὁ βαπτιστής</g>، المعمدان): <r v=\"Mark.6.14\"></r>، <r v=\"Mark.6.24\"></r>؛ مع المنصوب: <r v=\"John.4.1\"></r>، <r v=\"Acts.8.38\"></r>، <r v=\"1Cor.1.14\"></r>، <r v=\"1Cor.1.14\"></r>، <r v=\"1Cor.1.16\"></r>؛ مع مفعول مطلق من لفظه، <g>τὸ βάπτισμα</g>: <r v=\"Acts.19.4\"></r> (قارن <r v=\"Mark.10.38\"></r>، أعلاه)؛ المبني للمجهول: <b>اعتمد</b>، <b>نال المعمودية</b>: <r v=\"Matt.3.13\"></r>، <r v=\"Matt.3.14\"></r>، <r v=\"Matt.3.16\"></r>، <r v=\"Mark.16.16\"></r>، <r v=\"Luke.3.7\"></r>، <r v=\"Luke.3.12\"></r>، <r v=\"Luke.3.21\"></r>، <r v=\"Luke.7.29\"></r> (<g>τ. βάπτισμα</g>)، <r v=\"Luke.7.30\"></r>، <r v=\"Acts.2.41\"></r>، <r v=\"Acts.8.12\"></r>، <r v=\"Acts.8.13\"></r>، <r v=\"Acts.8.36\"></r>، <r v=\"Acts.9.18\"></r>، <r v=\"Acts.10.47\"></r>، <r v=\"Acts.16.15\"></r>، <r v=\"Acts.16.33\"></r>، <r v=\"Acts.18.8\"></r>؛ الصيغة الوسطى: <r v=\"Acts.22.16\"></r>؛</s> <s n=\"(b)\">مع حروف الجر: <g>ἐν</g>، عن العنصر (الذي يتم به العماد): <r v=\"Matt.3.6\"></r>، <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.4\"></r>، <r v=\"Mark.1.5\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، <r v=\"John.1.26\"></r>، <r v=\"John.1.31\"></r>، <r v=\"John.1.33\"></r>، <r v=\"John.3.23\"></r>، <r v=\"Acts.1.5\"></r>، <r v=\"Acts.2.38\"></r>، <r v=\"Acts.10.48\"></r>، <r v=\"Acts.11.16\"></r>، <r v=\"1Cor.10.2\"></r>؛ <g>εἰς</g>، عن العنصر أو الغاية أو النتيجة: <r v=\"Matt.3.11\"></r>، <r v=\"Matt.28.19\"></r>، <r v=\"Mark.1.9\"></r>، <r v=\"Acts.8.16\"></r>، <r v=\"Acts.19.3\"></r>، <r v=\"Acts.19.5\"></r>، <r v=\"Rom.6.3\"></r>، <r v=\"1Cor.1.13\"></r>، <r v=\"1Cor.1.15\"></r>، <r v=\"1Cor.10:2\"></r>، <r v=\"1Cor.12.13\"></r>، <r v=\"Gal.3.27\"></r>؛ مع القابل، <g>ὕδατι</g>: <r v=\"Luke.3.16\"></r>، <r v=\"Acts.1.5\"></r>، <r v=\"Acts.11.16\"></r>؛ <g>ὑπὲρ τῶν νεκρῶν</g>، ربما لتحقيق رغبة صديق متوفَّى: <r v=\"1Cor.15.29\"></r>.†</s> </s> </s>","en":"<f><o>βαπτίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>βάπτω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.5.14\"></r> (<h n=\"H2881\">טבל</h>), <r v=\"Isa.21.4\"></r>, <r v=\"Jdt.12.7\"></r>, <r v=\"LXX:Sir.34.30\"></r>*;]</e> </et> <s><b>to dip</b>, <b>immerse</b>, <b>sink</b>; <s n=\"1.\">generally (in Polyb., iii, 72, of soldiers wading breast-deep; in i, 51, of the sinking of ships); metaph., <b>to overwhelm</b> (<r v=\"Isa.21.4\"></r>; cf. MM, <i>Exp.</i>, x); c. cogn. acc., <g>βάπτισμα β.</g>, <r v=\"Mark.10.38\"></r>, <r v=\"Mark.10.39\"></r>, <r v=\"Luke.12.50\"></r>. Mid.,</s> <s n=\"2.\"><b>to perform ablutions</b>, <b>wash oneself</b>, <b>bathe</b> (<r v=\"2Kgs.5.14\"></r>, <r v=\"Jdt.12.7\"></r>, <r v=\"LXX:Sir.34.30\"></r>): <r v=\"Mark.7.4\"></r>; aor. pass, in same sense, <r v=\"Luke.11.38\"></r>.</s> <s n=\"3\">Of ablution, immersion, as a religious rite, <b>to baptize</b>; <s n=\"(a)\">absol.; <r v=\"Mark.1.4\"></r>, <r v=\"John.1.25\"></r>, <r v=\"John.1.26\"></r>, <r v=\"John.1.28\"></r> <r v=\"John.3.22\"></r>, <r v=\"John.3.23\"></r>, <r v=\"John.3.26\"></r> <r v=\"John.4.2\"></r> <r v=\"John.10.40\"></r>, <r v=\"1Cor.1.17\"></r>; <g>ὁ βαπτίζων</g> (= <g>ὁ βαπτιστής</g>, M, <i>Pr.</i>, 127), <r v=\"Mark.6.14\"></r>, <r v=\"Mark.6.24\"></r>; c. acc., <r v=\"John.4.1\"></r>, <r v=\"Acts.8.38\"></r>, <r v=\"1Cor.1.14\"></r> <r v=\"1Cor.1.14\"></r>, <r v=\"1Cor.1.16\"></r>; c. cogn. acc., <g>τὸ βάπτισμα</g>, <r v=\"Acts.19.4\"></r> (cf. <r v=\"Mark.10.38\"></r>, supr.); pass., <b>to be baptized</b>, <b>receive baptism</b>: <r v=\"Matt.3.13\"></r>, <r v=\"Matt.3.14\"></r>, <r v=\"Matt.3.16\"></r>, <r v=\"Mark.16.16\"></r>, <r v=\"Luke.3.7\"></r>, <r v=\"Luke.3.12\"></r>, <r v=\"Luke.3.21\"></r> <r v=\"Luke.7.29\"></r> (<g>τ. βάπτισμα</g>) <r v=\"Luke.7.30\"></r>, <r v=\"Acts.2.41\"></r> <r v=\"Acts.8.12\"></r>, <r v=\"Acts.8.13\"></r>, <r v=\"Acts.8.36\"></r> <r v=\"Acts.9.18\"></r> <r v=\"Acts.10.47\"></r> <r v=\"Acts.16.15\"></r>, <r v=\"Acts.16.33\"></r> <r v=\"Acts.18.8\"></r>; mid., <r v=\"Acts.22.16\"></r> (M, <i>Pr.,</i> 163);</s> <s n=\"(b)\">with prepositions: <g>ἐν</g>, of the element, <r v=\"Matt.3.6\"></r>, <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.4\"></r>, <r v=\"Mark.1.5\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, <r v=\"John.1.26\"></r>, <r v=\"John.1.31\"></r>, <r v=\"John.1.33\"></r> <r v=\"John.3.23\"></r>, <r v=\"Acts.1.5\"></r> <r v=\"Acts.2.38\"></r> <r v=\"Acts.10.48\"></r> <r v=\"Acts.11.16\"></r>, <r v=\"1Cor.10.2\"></r>; <g>εἰς</g>, of the element, purpose or result (Lft., <i>Notes</i>, 155), <r v=\"Matt.3.11\"></r> <r v=\"Matt.28.19\"></r>, <r v=\"Mark.1.9\"></r>, <r v=\"Acts.8.16\"></r> <r v=\"Acts.19.3\"></r>, <r v=\"Acts.19.5\"></r>, <r v=\"Rom.6.3\"></r>, <r v=\"1Cor.1.13\"></r>, <r v=\"1Cor.1.15\"></r> <r v=\"1Cor.10:2\"></r> <r v=\"1Cor.12.13\"></r>, <r v=\"Gal.3.27\"></r>; c. dat., <g>ὕδατι</g>, <r v=\"Luke.3.16\"></r>, <r v=\"Acts.1.5\"></r> <r v=\"Acts.11.16\"></r>; <g>ὑπὲρ τῶν νεκρῶν</g>, perh. to fulfil the wish of a dead friend, <r v=\"1Cor.15.29\"></r> (v. <i>ICC</i>, in l.; cf. <i>DB</i>, i, 238 ff.; <i>DCG</i>, i, 169<i>a</i>; ii, 605<i>b</i>; Cremer, 126).†</s> </s> </s>"},"G926":{"l":"βαρύς","o":6,"ar":"<f><o>βαρύς</o>، <g>-εῖα, ύ</g>،</f> <s><b>ثقيل</b>: <r v=\"Matt.23.4\"></r>. مجازيًا: <b>مُرهِق، شاقّ</b>: <g>ἐντολή</g>: <r v=\"1John.5.3\"></r>؛ <b>قاسٍ، شديد</b> (وربما <i>مَهيب</i>): <g>ἐπιστολή</g>: <r v=\"2Cor.10.10\"></r>؛ <b>ذو وزن، خطير</b>: <g>τὰ βαρύτερα τ. νόμου</g>: <r v=\"Matt.23.23\"></r>؛ <g>αἰτιώματα</g>: <r v=\"Acts.25.7\"></r>؛ <b>عنيف</b>، <b>قاسٍ</b> (<i>خاطف</i>): <g>λύκος</g>: <r v=\"Acts.20.29\"></r>.†</s>","en":"<f><o>βαρύς</o>, <g>-εῖα, ύ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3515\">כָּבֵד</h>;]</e> </et> <s><b>heavy</b>: <r v=\"Matt.23.4\"></r>. Metaph., <b>burdensome</b>: <g>ἐντολή</g>, <r v=\"1John.5.3\"></r>; <b>severe</b> (perh. <i>impressive</i>): <g>ἐπιστολή</g>, <r v=\"2Cor.10.10\"></r>; <b>weighty</b>: <g>τὰ βαρύτερα τ. νόμου</g>, <r v=\"Matt.23.23\"></r>; <g>αἰτιώματα</g>, <r v=\"Acts.25.7\"></r>; <b>violent</b>, <b>cruel</b> (EV, <i>grievous</i>): <g>λύκος</g>, <r v=\"Acts.20.29\"></r>.†</s>"},"G989":{"l":"βλάσφημος","o":4,"ar":"<f><o>βλάσφημος</o>، <g>-ον</g> </f> <s> <s n=\"(a)\"><b>شتّام، مُفترٍ، مجدِّف</b>: <r v=\"Acts.6.11\"></r>، <r v=\"2Tim.3.2\"></r>، <r v=\"2Pet.2.11\"></r> (قارن <r v=\"Jude.1.9\"></r>)؛ </s> <s n=\"(b)\">اسمًا: <b>مجدِّف</b>: <r v=\"1Tim.1.13\"></r>.†</s> </s>","en":"<f><o>βλάσφημος</o>, <g>-ον</g> </f> <et> <e t=\"derivation\">(&lt; <g>βλασ-</g>, of uncertain deriv., v. Thayer, Boisacq; + <g>φήμη</g>, speech), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.66.3\"></r> (<h n=\"H128,H205\">מְבָרֵךְ אָוֶן</h>), <r v=\"Wis.1.6\"></r>, <r v=\"Sir.3.16\"></r>, <r v=\"2Macc.9.28\"></r> <r v=\"2Macc.10.4\"></r>, <r v=\"2Macc.10.36\"></r> * ;]</e> </et> <s> <s n=\"(a)\"><b>evil-speaking, slanderous, blasphemous</b>: <r v=\"Acts.6.11\"></r>, <r v=\"2Tim.3.2\"></r>, <r v=\"2Pet.2.11\"></r> (cf. <r v=\"Jude.1.9\"></r>); </s> <s n=\"(b)\">as subst. <b>a blasphemer</b>: <r v=\"1Tim.1.13\"></r> (Cremer, 570).†</s> </s>"},"G997":{"l":"βοηθέω","o":8,"ar":"<f><o>βοηθέω</o>، <g>-ῶ</g> </f> <s><b>يأتي للنجدة، يُعين، يُغيث</b>: مطلقًا، <r v=\"Acts.21.28\"></r>؛ مع القابل، <r v=\"Matt.15.25\"></r>، <r v=\"Mark.9.22\"></r>، <r v=\"Mark.9.24\"></r> <r v=\"Acts.16.9\"></r>، <r v=\"2Cor.6.2\"></r> <i>(السبعينية)</i>، <r v=\"Heb.2.18\"></r>، <r v=\"Rev.12.16\"></r>.†</s>","en":"<f><o>βοηθέω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βοή</g> + <g>θέω</g>, <i>to run</i>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5826\">עזר</h> ;]</e> </et> <s><b>to come to aid, to help, succour</b>: absol., <r v=\"Acts.21.28\"></r>; c dat., <r v=\"Matt.15.25\"></r>, <r v=\"Mark.9.22\"></r>, <r v=\"Mark.9.24\"></r> <r v=\"Acts.16.9\"></r>, <r v=\"2Cor.6.2\"></r> <i>(LXX)</i>, <r v=\"Heb.2.18\"></r>, <r v=\"Rev.12.16\"></r>.†</s>"},"G955":{"l":"Βελιάρ","o":1,"ar":"<f><o>Βελιάρ</o>، <g>ὁ</g>، لا يُصرَّف.</f> <s><b>بليعال</b>، اسم من أسماء الشيطان: <r v=\"2Cor.6.15\"></r>.†</s>","en":"<f><o>Βελιάρ</o>, <g>ὁ</g>, indecl.</f> <et> <e t=\"derivation\">(another form of previous word, \"due to harsh Syriac pronunciation,\" or else &lt; Heb. <h n=\"H1078,H3293\">בֵּל יַעַר</h>, <i>lord of the forest</i>),</e> </et> <s><b>Beliar</b>, a name of Satan: <r v=\"2Cor.6.15\"></r> (v. <i>DB</i>, i, 269).†</s>"},"G952":{"l":"βέβηλος","o":5,"ar":"<f><o>βέβηλος</o>، <g>-ον</g></f> <s> <s n=\"1.\"><b>مباح أن يُداس</b>، <b>متاح للدخول</b>؛ ومن ثمّ: </s> <s n=\"2.\">(عكس <x><g>ἱερός</g></x>) <b>غير مقدَّس</b>، <b>دنس، باطل</b>: عن الأشياء، <r v=\"1Tim.4.7\"></r> <r v=\"1Tim.6.20\"></r>، <r v=\"2Tim.2.16\"></r>؛ عن الناس، <r v=\"1Tim.1.9\"></r>، <r v=\"Heb.12.16\"></r> (قارن <x><g>κοινός</g></x>).†</s></s>","en":"<f><o>βέβηλος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαίνω</g></x>, whence <x><g>βηλός</g></x>, <i>a threshold</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2455\">חֹל</h>;]</e> </et> <s> <s n=\"1.\"><b>permitted to be trodden</b>, <b>accessible</b> (v. <i>DCG</i>, ii, 422<i>b</i>); hence, </s> <s n=\"2.\">(opp. to <x><g>ἱερός</g></x>) <b>unhallowed</b>, <b>profane</b>: of things, <r v=\"1Tim.4.7\"></r> <r v=\"1Tim.6.20\"></r>, <r v=\"2Tim.2.16\"></r>; of men, <r v=\"1Tim.1.9\"></r>, <r v=\"Heb.12.16\"></r> (cf. <x><g>κοινός</g></x>; Cremer, 140).†</s></s>"},"G916":{"l":"βαρέω","o":6,"ar":"<f><o>βαρέω</o>، <g>-ῶ</g> (صيغة متأخرة من <g>βαρύνω</g>، انظره)،</f> <s><b>أثقل</b>، <b>أرهق</b>. وفي العهد الجديد بالمبني للمجهول فقط: <r v=\"Matt.26.43\"></r>، <r v=\"Luke.9.32\"></r> <r v=\"Luke.21.34\"></r>، <r v=\"2Cor.1.8\"></r> <r v=\"2Cor.5.4\"></r>، <r v=\"1Tim.5.16\"></r>.†</s>","en":"<f><o>βαρέω</o>, <g>-ῶ</g> (later form of <g>βαρύνω</g>, q.v.),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.7.14\"></r> (<h n=\"H3515\">כָּבֵד</h>), <r v=\"2Macc.13.9\"></r>*;]</e> </et> <s><b>to depress</b>, <b>weigh down</b>. In NT, in pass. only: <r v=\"Matt.26.43\"></r>, <r v=\"Luke.9.32\"></r> <r v=\"Luke.21.34\"></r>, <r v=\"2Cor.1.8\"></r> <r v=\"2Cor.5.4\"></r>, <r v=\"1Tim.5.16\"></r>.†</s>"},"G976":{"l":"βίβλος","o":10,"ar":"<f><o>βίβλος</o>، <g>-ου, ἡ</g> (صيغة أخرى لـ <x><g>βύβλος</g></x>، <i>البردي</i> المصري، الورق المصنوع من قشرته الليفية)، </f> <s><b>كتاب</b>، <b>درج</b>، وهو أقل استعمالاً بكثير من <g>βιβλίον</g>، ويحمل «إيحاءً بالقداسة والتوقير»: <r v=\"Matt.1.1\"></r> <r v=\"Mark.12.26\"></r>، <r v=\"Luke.3.4\"></r> <r v=\"Luke.20.42\"></r> <r v=\"Acts.1.20\"></r> <r v=\"Acts.7.42\"></r> <r v=\"Acts.19.19\"></r>؛ <g>β. τ. ζωῆς</g>، <r v=\"Phil.4.3\"></r>، <r v=\"Rev.3.5\"></r> <r v=\"Rev.20.15\"></r>.†</s>","en":"<f><o>βίβλος</o>, <g>-ου, ἡ</g> (variant form of <x><g>βύβλος</g></x>, the Egyptian <i>papyrus</i>, paper made from its fibrous coat), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5612\">סֶפֶר</h>, the form <g>βύβ-</g> being sometimes used;]</e> </et> <s><b>a book</b>, <b>a roll</b>, used much less freq. than <g>βιβλίον</g>, and with a \"connotation of sacredness and veneration\" (MM, <i>Exp.</i>, x), <r v=\"Matt.1.1\"></r> <r v=\"Mark.12.26\"></r>, <r v=\"Luke.3.4\"></r> <r v=\"Luke.20.42\"></r> <r v=\"Acts.1.20\"></r> <r v=\"Acts.7.42\"></r> <r v=\"Acts.19.19\"></r>; <g>β. τ. ζωῆς</g>, <r v=\"Phil.4.3\"></r>, <r v=\"Rev.3.5\"></r> <r v=\"Rev.20.15\"></r>.†</s>"},"G979":{"l":"βίος","o":10,"ar":"<f><o>βίος</o>، <g>-ου, ὁ</g>،</f> <s n=\"1.\"><b>مدة</b> أو <b>مسيرة الحياة</b>، <b>حياة، عيشة</b>: <r v=\"Luke.8.14\"></r>، <r v=\"1Tim.2.2\"></r>، <r v=\"2Tim.2.4\"></r>، <r v=\"1John.2.16\"></r>.</s> <s n=\"2.\"><b>معيشة</b>، <b>رزق</b>، <b>موارد</b> (في <r v=\"Prov.31.14\"></r> ترجمةً لـ <h n=\"H3899\">לֶחֶם</h>): <r v=\"Mark.12.44\"></r>، <r v=\"Luke.8.43\"></r> <r v=\"Luke.15.12\"></r>، <r v=\"Luke.15.30\"></r> <r v=\"Luke.21.4\"></r>، <r v=\"1John.3.17\"></r>.†</s>","en":"<f><o>βίος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3117\">יָמִים</h>;]</e> </et> <s n=\"1.\"><b>period</b> or <b>course of life</b>, <b>life</b>: <r v=\"Luke.8.14\"></r>, <r v=\"1Tim.2.2\"></r>, <r v=\"2Tim.2.4\"></r>, <r v=\"1John.2.16\"></r>.</s> <s n=\"2.\"><b>living</b>, <b>livelihood</b>, <b>means</b> (in <r v=\"Prov.31.14\"></r> for <h n=\"H3899\">לֶחֶם</h>; v. <i>DCG</i>, ii, 39<i>a</i>): <r v=\"Mark.12.44\"></r>, <r v=\"Luke.8.43\"></r> <r v=\"Luke.15.12\"></r>, <r v=\"Luke.15.30\"></r> <r v=\"Luke.21.4\"></r>, <r v=\"1John.3.17\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ζωή</g></x>, is life <i>intensive</i>, \"<l>vita quâ vivimus</l>,\" the vital principle; <g>βίος</g>, life <i>extensive</i>, \"vita quam vivimus,\" (1) the period of life, (2) the means by which it is sustained. Hence, in cl., <g>ζ.</g>, being confined to the physical life common to men and animals, is the inferior word (cf. <i>zoology</i>, <i>biography</i>). In NT, <x><g>ζωή</g></x> is elevated into the ethical and spiritual sphere (cf. Tr., <i>Syn.</i>, § xxvii).</sy>"},"G975":{"l":"βιβλίον","o":34,"ar":"<f><o>βιβλίον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>ورقة</b>، <b>رسالة</b>، <b>وثيقة مكتوبة</b>: <g>β. ἀποστασίου</g>، <b>كتاب طلاق</b>، <r v=\"Matt.19.7\"></r>، <r v=\"Mark.10.4\"></r>.</s> <s n=\"2.\"><b>كتاب</b>، <b>درج</b>: <r v=\"Luke.4.17\"></r>، <r v=\"Luke.4.20\"></r> <r v=\"John.20.30\"></r> <r v=\"John.21.25\"></r>، <r v=\"Gal.3.10\"></r>، <r v=\"2Tim.4.13\"></r>، <r v=\"Heb.9.19\"></r> <r v=\"Heb.10.7\"></r>، <r v=\"Rev.1.11\"></r> <r v=\"Rev.5.1-Rev.5.9\"></r> <r v=\"Rev.6.14\"></r> <r v=\"Rev.10.8\"></r> <r v=\"Rev.20.12\"></r> <r v=\"Rev.22.7-Rev.22.19\"></r>؛ <g>β. τ. ζωῆς</g>، <r v=\"Rev.13.8\"></r> <r v=\"Rev.17.8\"></r> <r v=\"Rev.20.12\"></r> <r v=\"Rev.21.27\"></r>.†</s>","en":"<f><o>βιβλίον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dim. of <x><g>βίβλος</g></x>, q.v.),</e> <e t=\"septuagint\">[in LXX also in the alternat. form <g>βυβ-</g>, chiefly for <h n=\"H5612\">סֶפֶר</h> and the most freq. of the cognate forms;]</e> </et> <s n=\"1.\"><b>a paper</b>, <b>letter</b>, <b>written document</b>: <g>β. ἀποστασίου</g>, <b>bill of divorce</b>, <r v=\"Matt.19.7\"></r>, <r v=\"Mark.10.4\"></r>.</s> <s n=\"2.\"><b>a book</b>, <b>a roll</b>: <r v=\"Luke.4.17\"></r>, <r v=\"Luke.4.20\"></r> <r v=\"John.20.30\"></r> <r v=\"John.21.25\"></r>, <r v=\"Gal.3.10\"></r>, <r v=\"2Tim.4.13\"></r>, <r v=\"Heb.9.19\"></r> <r v=\"Heb.10.7\"></r>, <r v=\"Rev.1.11\"></r> <r v=\"Rev.5.1-Rev.5.9\"></r> <r v=\"Rev.6.14\"></r> <r v=\"Rev.10.8\"></r> <r v=\"Rev.20.12\"></r> <r v=\"Rev.22.7-Rev.22.19\"></r>; <g>β. τ. ζωῆς</g>, <r v=\"Rev.13.8\"></r> <r v=\"Rev.17.8\"></r> <r v=\"Rev.20.12\"></r> <r v=\"Rev.21.27\"></r>.†</s>"},"G968":{"l":"βῆμα","o":12,"ar":"<f><o>βῆμα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>خطوة</b>، <b>وطأة قدم</b>: <r v=\"Acts.7.5\"></r>.</s> <s n=\"2.\"><b>موضع مرتفع</b>، <b>منصّة</b> يُصعد إليها بدرجات، وأصلاً المنصّة التي في البنيكس بأثينا حيث كانت تُلقى الخطب؛ وكثيرًا عن <b>كرسي الولاية</b> أو <b>كرسي القضاء</b> لحاكم أو والٍ روماني: <r v=\"Matt.27.19\"></r>، <r v=\"John.19.13\"></r>، <r v=\"Acts.12.21\"></r>، <r v=\"Acts.18.12\"></r>، <r v=\"Acts.18.16\"></r>، <r v=\"Acts.18.17\"></r> <r v=\"Acts.25.6\"></r>، <r v=\"Acts.25.10\"></r>، <r v=\"Acts.25.17\"></r>؛ <g>β. τοῦ θεοῦ</g>، <r v=\"Rom.14.10\"></r>؛ <g>τ. Χριστοῦ</g>، <r v=\"2Cor.5.10\"></r>.†</s>","en":"<f><o>βῆμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαίνω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.2.5\"></r> (<h n=\"H4096\">מִדְרָךְ</h>), <r v=\"Neh.8.4\"></r> (<h n=\"H4026\">מִגְדָּל</h>), <r v=\"1Esd.9.42\"></r>, <r v=\"Sir.19.30\"></r> <r v=\"Sir.45.9\"></r>, <r v=\"2Macc.13.26\"></r>*;]</e> </et> <s n=\"1.\"><b>a step</b>, <b>stride</b>, <b>pace</b>: <r v=\"Acts.7.5\"></r>.</s> <s n=\"2.\"><b>a raised place</b>, <b>a platform</b> reached by steps, originally that in the Pnyx at Athens from which orations were made; freq. of the <b>tribune</b> or <b>tribunal</b> of a Roman magistrate or ruler: <r v=\"Matt.27.19\"></r>, <r v=\"John.19.13\"></r>, <r v=\"Acts.12.21\"></r>, <r v=\"Acts.18.12\"></r>, <r v=\"Acts.18.16\"></r>, <r v=\"Acts.18.17\"></r> <r v=\"Acts.25.6\"></r>, <r v=\"Acts.25.10\"></r>, <r v=\"Acts.25.17\"></r>; <g>β. τοῦ θεοῦ</g>, <r v=\"Rom.14.10\"></r>; <g>τ. Χριστοῦ</g>, <r v=\"2Cor.5.10\"></r>.†</s>"},"G909":{"l":"βαπτισμός","o":4,"ar":"<f>*† <o>βαπτισμός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\"><b>غمس</b>، <b>غسل</b>، <b>تطهير</b>: <r v=\"Mark.7.4\"></r>؛ عن الطقوس اليهودية، <r v=\"Heb.9.10\"></r>؛ وفي <r v=\"Heb.6.2\"></r>، <g>βαπτισμῶν διδαχήν</g> (<g>-ῆς</g>)، يبدو أن صيغة الجمع وهذه الصيغة الخاصة استُعملتا لتشملا المعمودية المسيحية مع طقوس التطهير الأخرى.</s> <s n=\"2.\"><b>معمودية</b>: عند الكتّاب المتأخرين (عن معمودية يوحنا) وعند بعض الآباء. ولا ترد بهذا المعنى في العهد الجديد، إلا إذا قُرئ <g>ἐν τ. βαπτισμῷ</g>، <i>في فعل المعمودية</i>، في <r v=\"Col.2.12\"></r> (وفي قراءة أخرى <g>-ματι</g>).†</s>","en":"<f>*† <o>βαπτισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαπτίζω</g></x>) , prop., the act of which <x><g>βάπτισμα</g></x> is the result;</e> </et> <s n=\"1.\"><b>a dipping</b>, <b>washing</b>, <b>lustration</b>: <r v=\"Mark.7.4\"></r>; of Jewish ceremonial, <r v=\"Heb.9.10\"></r>; in <r v=\"Heb.6.2\"></r>, <g>βαπτισμῶν διδαχήν</g> (<g>-ῆς</g>), \"the pl. and the peculiar form seem to be used to include Christian baptism with other lustral rites\" (Westc, in l.).</s> <s n=\"2.\"><b>baptism</b>: FlJ, Ant., 18, 5, 2 (of John's baptism), and some Fathers (v. Soph., s.v.). Not so in NT, unless <g>ἐν τ. βαπτισμῷ</g>, <i>in the act of baptism</i>, <r v=\"Col.2.12\"></r>, be read with Tr. (Rec., WH, R, <g>-ματι</g>).†</s>"},"G941":{"l":"βαστάζω","o":27,"ar":"<f><o>βαστάζω</o>،</f> <s n=\"1.\"><b>يرفع</b> باليدين، <b>يحمل</b>: <g>λίθους</g>، <r v=\"John.10.31\"></r>. </s> <s n=\"2.\"><b>يحمل</b>، <b>يحتمل</b>، كحِمل، ومجازيًا <b>يحتمل، يصبر على</b>؛ <r v=\"Matt.3.11\"></r>، <r v=\"Matt.20.12\"></r>، <r v=\"Mark.14.13\"></r>، <r v=\"Luke.7.14\"></r>، <r v=\"Luke.10.7\"></r>، 11:27، 14:27، 22:10، <r v=\"John.16.12\"></r>، <r v=\"John.19.17\"></r>، <r v=\"Acts.3.2\"></r>، <r v=\"Acts.9.15\"></r>، <r v=\"Acts.15.1\"></r>، <r v=\"Acts.21.35\"></r>، <r v=\"Rom.11.18\"></r>، <r v=\"Rom.15.1\"></r>، <r v=\"Gal.5.10\"></r>، <r v=\"Gal.6.2\"></r>، <r v=\"Gal.6.5\"></r>، <r v=\"Gal.6.17\"></r>، <r v=\"Rev.2.2\"></r>، <r v=\"Rev.2.3\"></r>، <r v=\"Rev.17.7\"></r>. </s> <s n=\"3.\">وعند الكتّاب المتأخرين، <s n=\"(a)\"><b>يأخذ، يرفع (يُزيل)</b>؛ <r v=\"Matt.8.17\"></r> (<r v=\"Isa.53.4\"></r>، بحسب العبرية)؛ </s> <s n=\"(b)\"><b>يختلس</b>، <b>يسرق</b>: <r v=\"John.12.6\"></r>، <r v=\"John.20.15\"></r>.†</s> </s>","en":"<f><o>βαστάζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.16.30\"></r> (<h n=\"H5186\">נטה</h>), <r v=\"Ruth.2.16\"></r>, <r v=\"2Sam.23.5\"></r>, <r v=\"2Kgs.18.14\"></r> and <r v=\"Job.21.3\"></r> (<h n=\"H5375\">נשׂא</h>), <r v=\"Sir.6.25\"></r>, <r v=\"Bel.1.36\"></r>*;]</e> </et> <s n=\"1.\"><b>to take up</b> with the hands, <b>to lift</b>: <g>λίθους</g>, <r v=\"John.10.31\"></r>. </s> <s n=\"2.\"><b>to bear</b>, <b>to carry</b>, as a burden, and metaph., <b>to endure</b>; <r v=\"Matt.3.11\"></r> <r v=\"Matt.20.12\"></r>, <r v=\"Mark.14.13\"></r>, <r v=\"Luke.7.14\"></r> <r v=\"Luke.10.7\"></r> 11:27 14:27 22:10, <r v=\"John.16.12\"></r> <r v=\"John.19.17\"></r>, <r v=\"Acts.3.2\"></r> <r v=\"Acts.9.15\"></r> <r v=\"Acts.15.1\"></r> <r v=\"Acts.21.35\"></r>, <r v=\"Rom.11.18\"></r> <r v=\"Rom.15.1\"></r>, <r v=\"Gal.5.10\"></r> <r v=\"Gal.6.2\"></r>, <r v=\"Gal.6.5\"></r> <r v=\"Gal.6.17\"></r>, <r v=\"Rev.2.2\"></r>, <r v=\"Rev.2.3\"></r> <r v=\"Rev.17.7\"></r>. </s> <s n=\"3.\">In late writers (MM, <i>Exp.</i>, ii, iii, x), <s n=\"(a)\"><b>to take away</b>; <r v=\"Matt.8.17\"></r> (<r v=\"Isa.53.4\"></r>, Heb.); </s> <s n=\"(b)\"><b>to carry off</b>, <b>steal</b>: <r v=\"John.12.6\"></r> <r v=\"John.20.15\"></r>.†</s> </s>"},"G935":{"l":"βασιλεύς","o":115,"ar":"<f><o>βασιλεύς</o>، <g>-έως, ὁ</g>،</f> <s><b>ملك</b>: <r v=\"Matt.1.6\"></r>، <r v=\"Matt.2.1\"></r>؛ ويُطلق تأدبًا على هيرودس رئيس الربع، <r v=\"Matt.14.9\"></r>؛ وعلى الإمبراطور الروماني، <r v=\"1Pet.2.13\"></r>، <r v=\"1Pet.2.17\"></r>؛ وعلى المسيح في عبارة <g>ὁ β. τ. Ἰουδαίων</g>، <r v=\"Matt.2.2\"></r>، وفي مواضع أخرى؛ <g>τοῦ Ἰσραήλ</g>، <r v=\"Mark.15.32\"></r>، <r v=\"John.1.50\"></r>، <r v=\"John.12.13\"></r>؛ وعلى الله، <r v=\"Matt.5.35\"></r>، <r v=\"1Tim.1.17\"></r>، <r v=\"Rev.15.3\"></r>؛ <g>β. βασιλέων</g>، <r v=\"Rev.17.14\"></r>، <r v=\"Rev.19.16\"></r>؛ <g>β. τ. βασιλευόντων</g>، <r v=\"1Tim.6.15\"></r>.†</s>","en":"<f><o>βασιλεύς</o>, <g>-έως, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4428\">מֶלֶךְ</h>;]</e> </et> <s><b>a king</b>: <r v=\"Matt.1.6\"></r> <r v=\"Matt.2.1\"></r>; used by courtesy of Herod the Tetrarch, <r v=\"Matt.14.9\"></r>; of the Roman Emperor, as freq. in <g>κοινή</g> (Deiss., <i>LAE</i>, p. 367), <r v=\"1Pet.2.13\"></r>, <r v=\"1Pet.2.17\"></r>; of the Christ, in the phrase <g>ὁ β. τ. Ἰουδαίων</g>, <r v=\"Matt.2.2\"></r>, al.; <g>τοῦ Ἰσραήλ</g>, <r v=\"Mark.15.32\"></r>, <r v=\"John.1.50\"></r> <r v=\"John.12.13\"></r>; of God, <r v=\"Matt.5.35\"></r>, <r v=\"1Tim.1.17\"></r>, <r v=\"Rev.15.3\"></r>; <g>β. βασιλέων</g>, <r v=\"Rev.17.14\"></r> <r v=\"Rev.19.16\"></r>; <g>β. τ. βασιλευόντων</g>, <r v=\"1Tim.6.15\"></r> (on the associations of the word to Jewish Hellenists, v. <i>Cl. Rev.</i>, i, 7).†</s>"},"G950":{"l":"βεβαιόω","o":8,"ar":"<f><o>βεβαιόω</o>، <g>-ῶ</g></f> <s><b>يثبّت</b>، <b>يرسّخ</b>، <b>يضمن</b>، عن الأشياء: <g>λόγον</g>، <r v=\"Mark.16.20\"></r>؛ <g>ἐπαγγελίας</g>، <r v=\"Rom.15.8\"></r>؛ عن الأشخاص: <r v=\"1Cor.1.8\"></r>، <r v=\"2Cor.1.21\"></r>. المبني للمجهول: <r v=\"1Cor.1.6\"></r>، <r v=\"Col.2.7\"></r>، <r v=\"Heb.2.3\"></r> <r v=\"Heb.13.9\"></r> (وهو مصطلح قانوني أتيكي بمعنى <i>يضمن</i> صحة الشراء، أو <i>يثبت</i> حق الملكية أو <i>يؤكده</i>؛ انظر المدخل التالي، وقارن <g>δια-β.</g>).†</s>","en":"<f><o>βεβαιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βέβαιος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"LXX:Ps.41.12\"></r> (<h n=\"H5324\">נצב</h> hi.), <r v=\"Ps.119.28\"></r> (<h n=\"H6965\">קוּם</h> pi.), <r v=\"3Macc.5.42\"></r>*;]</e> </et> <s><b>to confirm</b>, <b>establish</b>, <b>secure</b>, of things (cl.): <g>λόγον</g>, <r v=\"Mark.16.20\"></r>; <g>ἐπαγγελίας</g>, <r v=\"Rom.15.8\"></r>; of persons (<i>DCG</i>, ii, 605): <r v=\"1Cor.1.8\"></r>, <r v=\"2Cor.1.21\"></r>. Pass., <r v=\"1Cor.1.6\"></r>, <r v=\"Col.2.7\"></r>, <r v=\"Heb.2.3\"></r> <r v=\"Heb.13.9\"></r> (as an Attic legal term, <i>to guarantee</i> the validity of a purchase, <i>establish</i> or <i>confirm</i> a title; v. next word, Cremer, 139; cf. <g>δια-β.</g>).†</s>"},"G983":{"l":"βλαβερός","o":1,"ar":"<f><o>βλαβερός</o>، <g>-ά, -όν</g> </f> <s><b>مُضرّ</b>: <r v=\"1Tim.6.9\"></r>.†</s>","en":"<f><o>βλαβερός</o>, <g>-ά, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <g>βλάπτω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.10.26\"></r>* ;]</e> </et> <s><b>hurtful</b>: <r v=\"1Tim.6.9\"></r>.†</s>"},"G911":{"l":"βάπτω","o":4,"ar":"<f><o>βάπτω</o>،</f> <s n=\"(a)\"><b>غمس</b>: <r v=\"Luke.16.24\"></r>، <r v=\"John.13.26\"></r>؛</s> <s n=\"(b)\"><b>غمس في الصبغ</b>، <b>صبغ</b>: <r v=\"Rev.19.13\"></r> (وفي قراءات أخرى <g>ῥεραντισμένον</g>، <g>περιρεραμμένον</g>، <g>ῥεραμμένον</g>).†</s>","en":"<f><o>βάπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2881\">טבל</h>;]</e> </et> <s n=\"(a)\"><b>to dip</b>: <r v=\"Luke.16.24\"></r>, <r v=\"John.13.26\"></r> (<g>ἐμβ-</g>, L);</s> <s n=\"(b)\"><b>to dip in dye</b>, <b>to dye</b>: <r v=\"Rev.19.13\"></r> (Rec.; <g>ῥεραντισμένον</g>, WH; <g>περιρεραμμένον</g>, T; <g>ῥεραμμένον</g>, Swete, in l., q.v.).†</s>"},"G937":{"l":"βασιλικός","o":5,"ar":"<f><o>βασιλικός</o>، <g>-ή, -όν</g></f> <s><b>ملكي</b>، <b>خاص بالملك</b>: <g>χώρα</g>، <r v=\"Acts.12.20\"></r>؛ <g>ἐσθής</g>، <r v=\"Acts.12.21\"></r>؛ <g>νόμος β.</g>، <b>الناموس الملوكي</b>، أي «ناموس يحكم سائر النواميس، فله لذلك صفة ملكية خاصة»، أو لأنه صادر عن ملك، <r v=\"Jas.2.8\"></r>؛ <g>τις</g>، <b>رجل في خدمة الملك</b>، <b>خادم في البلاط الملكي</b>، <r v=\"John.4.46\"></r>، <r v=\"John.4.49\"></r>.†</s>","en":"<f><o>βασιλικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βασιλεύς</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4428\">מֶלֶךְ</h> and its cognates;]</e> </et> <s><b>royal</b>, <b>belonging to a king</b>: <g>χώρα</g>, <r v=\"Acts.12.20\"></r>; <g>ἐσθής</g>, <r v=\"Acts.12.21\"></r>; <g>νόμος β.</g>, <b>a supreme law</b>, \"a law which governs other laws and so has a specially regal character\" (Hort), or because made by a king (<i>LAE</i>, p. 367<i>3</i>), <r v=\"Jas.2.8\"></r>; <g>τις</g>, <b>one in the service of a king</b>, <b>a courtier</b>, <r v=\"John.4.46\"></r>, <r v=\"John.4.49\"></r> (WH, mg., <g>βασιλίσκος</g>).†</s>"},"G938":{"l":"βασίλισσα","o":4,"ar":"<f><o>βασίλισσα</o>، <g>-ης, ἡ</g></f> <s><b>ملكة</b>: <r v=\"Matt.12.42\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"Acts.8.27\"></r>، <r v=\"Rev.18.7\"></r>.†</s>","en":"<f><o>βασίλισσα</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(in Attic, <g>βασιλεία</g>, <g>βασιλίς</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4436\">מַלְכָּה</h>;]</e> </et> <s><b>a queen</b>: <r v=\"Matt.12.42\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"Acts.8.27\"></r>, <r v=\"Rev.18.7\"></r>.†</s>"},"G990":{"l":"βλέμμα","o":1,"ar":"<f>* <o>βλέμμα</o>، <g>-τος, τό</g> </f> <s><b>نظرة، لمحة</b>: <g>βλέμματι καὶ ἀκοῇ</g>، <r v=\"2Pet.2.8\"></r>، <b>بالنظر والسمع</b>.†</s>","en":"<f>* <o>βλέμμα</o>, <g>-τος, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>βλέπω</g>), </e> </et> <s><b>a look, a glance</b>: <g>βλέμματι καὶ ἀκοῇ</g>, <r v=\"2Pet.2.8\"></r>, <b>sight and hearing</b>, a sense not found for <g>β.</g> in Gk. lit., but perh. recognized in the vernacular (<i>ICC</i>, in l.)†</s>"},"G946":{"l":"βδέλυγμα","o":6,"ar":"<f>† <o>βδέλυγμα</o>، <g>-τος, τό</g></f> <s><b>رجس</b>، <b>شيء مكروه</b>: <r v=\"Luke.16.15\"></r>، <r v=\"Rev.17.4\"></r>، <r v=\"Rev.17.5\"></r>، <r v=\"Rev.21.27\"></r>؛ <g>τὸ</g> <g>β. τ. ἐρημώσεως</g> (<r v=\"Dan.12.11\"></r>، قارن <r v=\"1Macc.1.54\"></r>)، <r v=\"Mark.13.14\"></r>، <r v=\"Matt.24.15\"></r>.†</s>","en":"<f>† <o>βδέλυγμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βδελύσσω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8263,H8441\">שֶׁקֶץ ,תּוֹעֵבָה</h>;]</e> </et> <s><b>an abomination</b>, <b>a detestable thing</b>: <r v=\"Luke.16.15\"></r>, <r v=\"Rev.17.4\"></r>, <r v=\"Rev.17.5\"></r> <r v=\"Rev.21.27\"></r>; <g>τὸ</g> <g>β. τ. ἐρημώσεως</g> (<r v=\"Dan.12.11\"></r>, cf . <r v=\"1Macc.1.54\"></r>; <i>DB</i>, i, 12 f.; <i>DCG</i>, i, 6 f.), <r v=\"Mark.13.14\"></r>, <r v=\"Matt.24.15\"></r> (Cremer, 138).†</s>"},"G996":{"l":"βοήθεια","o":2,"ar":"<f><o>βοήθεια</o>، <g>-ας, ἡ</g> (انظر تحت مدخل <g>βοηθέω</g>)، </f> <s><b>عون، معونة</b>: <r v=\"Heb.4.16\"></r>؛ في الجمع، <b>معونات</b>، أي أحزمة تُلفّ حول السفينة لتشدّها، مصطلح بحري فني: <r v=\"Acts.27.17\"></r>.†</s>","en":"<f><o>βοήθεια</o>, <g>-ας, ἡ</g> (v.s. <g>βοηθέω</g>), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5828\">עֵזֶר</h>, etc. ;]</e> </et> <s><b>help</b>: <r v=\"Heb.4.16\"></r>; pl., <b>helps, \"frapping,\"</b> a technical nautical term (MM, <i>Exp.</i>, x; <i>DB</i>, <i>ext.</i>, 367): <r v=\"Acts.27.17\"></r>.†</s>"},"G928":{"l":"βασανίζω","o":12,"ar":"<f><o>βασανίζω</o></f> <s> <s n=\"1.\">أصلاً: <b>فرك على حجر المحكّ</b>، <b>امتحن</b>.</s> <s n=\"2.\"><b>استجوب بالتعذيب</b>، ومن ثَمّ عمومًا: <b>عذّب</b>، <b>عنّى</b>، <b>ضايق</b>: <r v=\"Matt.8.6\"></r>، <r v=\"Matt.8.29\"></r> <r v=\"Matt.14.24\"></r>، <r v=\"Mark.5.7\"></r> <r v=\"Mark.6.48\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"2Pet.2.8\"></r>، <r v=\"Rev.9.5\"></r> <r v=\"Rev.11.10\"></r> <r v=\"Rev.12.2\"></r> <r v=\"Rev.14.10\"></r> <r v=\"Rev.20.10\"></r>.†</s> </s>","en":"<f><o>βασανίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>βάσανος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.5.3\"></r>, <r v=\"Sir.4.17\"></r>, and freq. in Wi, II, IV Mac;]</e> </et> <s> <s n=\"1.\">prop., <b>to rub on the touchstone</b>, <b>put to the test</b>.</s> <s n=\"2.\"><b>to examine by torture</b>, hence, generally, <b>to torture</b>, <b>torment</b>, <b>distress</b>: <r v=\"Matt.8.6\"></r>, <r v=\"Matt.8.29\"></r> <r v=\"Matt.14.24\"></r>, <r v=\"Mark.5.7\"></r> <r v=\"Mark.6.48\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"2Pet.2.8\"></r>, <r v=\"Rev.9.5\"></r> <r v=\"Rev.11.10\"></r> <r v=\"Rev.12.2\"></r> <r v=\"Rev.14.10\"></r> <r v=\"Rev.20.10\"></r>.†</s> </s>"},"G929":{"l":"βασανισμός","o":6,"ar":"<f>** <o>βασανισμός</o>، <g>-οῦ, ὁ</g></f> <s><b>تعذيب</b>، <b>عذاب</b>: <r v=\"Rev.9.5\"></r> <r v=\"Rev.14.11\"></r> <r v=\"Rev.18.7\"></r>، <r v=\"Rev.18.10\"></r>، <r v=\"Rev.18.15\"></r>.†</s>","en":"<f>** <o>βασανισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βασανίζω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.9.6\"></r> <r v=\"4Macc.11.2\"></r>*;]</e> </et> <s><b>torture</b>, <b>torment</b>: <r v=\"Rev.9.5\"></r> <r v=\"Rev.14.11\"></r> <r v=\"Rev.18.7\"></r>, <r v=\"Rev.18.10\"></r>, <r v=\"Rev.18.15\"></r>.†</s>"},"G904":{"l":"Βαλάκ","o":1,"ar":"<f><o>Βαλάκ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H1111\">בָּלָק</h>)، </f> <s><b>بالاق</b>؛ (<r v=\"Num.22.2\"></r>): <r v=\"Rev.2.14\"></r>.†</s>","en":"<f><o>Βαλάκ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H1111\">בָּלָק</h>), </f> <s><b>Balak</b>; (<r v=\"Num.22.2\"></r>): <r v=\"Rev.2.14\"></r>.†</s>"},"G934":{"l":"βασίλειος","o":1,"ar":"<f><o>βασίλειος</o>، <g>-ον</g> (وأيضًا <g>-α, -ον</g>)؛</f> <s><b>ملوكي</b>: <r v=\"1Pet.2.9\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>βασίλειος</o>, <g>-ον</g> (also <g>-α, -ον</g>;</f> <et> <e t=\"derivation\">&lt; <x><g>βασιλεύς</g></x>),</e> <e t=\"septuagint\">[in LXX; <r v=\"Exod.19.6\"></r>, <r v=\"Deut.3.10\"></r> (<h n=\"H4467\">מַמְלָכָה</h>), <r v=\"Exod.23.22\"></r>, <r v=\"Wis.18.15\"></r>, <r v=\"3Macc.3.28\"></r>, <r v=\"4Macc.3.8\"></r>*;]</e> </et> <s><b>royal</b>: <r v=\"1Pet.2.9\"></r><i>(LXX)</i> (v. Hort, in l.).†</s>"},"G913":{"l":"Βαράκ","o":1,"ar":"<f><o>Βαράκ</o>، <g>ὁ</g>، لا يُصرَّف</f> <s><b>باراق</b> (<r v=\"Judg.4.6\"></r>): <r v=\"Heb.11.32\"></r>.†</s>","en":"<f><o>Βαράκ</o>, <g>ὁ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1301\">בָּרָק</h>),</e> </et> <s><b>Barak</b> (<r v=\"Judg.4.6\"></r>): <r v=\"Heb.11.32\"></r>.†</s>"},"G906":{"l":"βάλλω","o":122,"ar":"<f><o>βάλλω</o>،</f> <s>أصلاً عن السلاح أو المقذوف؛ ثم عمومًا عن الأشياء والأشخاص، حرفيًا ومجازيًا، <b>رمى، ألقى، طرح، وضع</b>: مع المنصوب، يليه <g>εἰς</g>، <r v=\"Matt.4.18\"></r>، وكثيرًا <g>ἐπί</g>، <r v=\"Matt.10.34\"></r>؛ <g>κάτω</g>، <r v=\"Matt.4.6\"></r>؛ <g>ἔξω</g>، <r v=\"Matt.5.13\"></r>؛ <g>ἀπό</g>، <r v=\"Matt.5.29\"></r>؛ <g>ἐκ</g>، <r v=\"Mark.12.44\"></r>؛ <g>δρέπανον</g>، <r v=\"Rev.14.19\"></r>؛ <g>μάχαιραν</g>، <r v=\"Matt.10.34\"></r>؛ <g>κλῆρον</g>، <r v=\"Matt.27.35\"></r>؛ عن السوائل، <b>صبّ</b>: <r v=\"Matt.9.17\"></r>، <r v=\"John.13.5\"></r>؛ المبني للمجهول، <b>طُرح، اضطجع مريضًا</b>: <r v=\"Matt.9.2\"></r>؛ <g>ἐβλήθη</g> (ماضٍ بسيط لا يدل على زمن)، <r v=\"John.15.6\"></r>؛ لازم، <b>اندفع، هبّ</b>: <r v=\"Acts.27.14\"></r>. مجازيًا، <g>β. εἰς τ. καρδίαν</g>، <r v=\"John.13.2\"></r> (قارن <g>ἀμφι-</g>، <g>ἀνα-</g>، <g>ἀντι-</g>، <g>ἀπο-</g>، <g>δια-</g>، <g>ἐκ-</g>، <g>ἐμ-</g>، <g>παρ-εμ-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>μετα-</g>، <g>παρα-</g>، <g>περι-</g>، <g>προ-</g>، <g>συμ-</g>، <g>ὑπερ-</g>، <g>ὑπο-βάλλω</g>).</s>","en":"<f><o>βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5307\">נפל</h>, <h n=\"H7760\">שׂום</h>, <h n=\"H3032\">ידד</h>, etc.;]</e> </et> <s>prop., of a weapon or missile; then generally, of things and persons, lit. and metaph., <b>to throw, cast, put, place</b>: c. acc., seq. <g>εἰς</g>, <r v=\"Matt.4.18\"></r>, and freq. <g>ἐπί</g>, <r v=\"Matt.10.34\"></r>; <g>κάτω</g>, <r v=\"Matt.4.6\"></r>; <g>ἔξω</g>, <r v=\"Matt.5.13\"></r>; <g>ἀπό</g>, <r v=\"Matt.5.29\"></r>; <g>ἐκ</g>, <r v=\"Mark.12.44\"></r>; <g>δρέπανον</g>, <r v=\"Rev.14.19\"></r>; <g>μάχαιραν</g>, <r v=\"Matt.10.34\"></r>; <g>κλῆρον</g>, <r v=\"Matt.27.35\"></r>; of fluids, <b>to pour</b>: <r v=\"Matt.9.17\"></r>, <r v=\"John.13.5\"></r>; pass., <b>to be laid, to lie ill</b>: <r v=\"Matt.9.2\"></r>; <g>ἐβλήθη</g> (timeless aor., M, <i>Pr.</i>, 134), <r v=\"John.15.6\"></r>; intrans., <b>to rush</b> (Bl., §53, 1): <r v=\"Acts.27.14\"></r>. Metaph., <g>β. εἰς τ. καρδίαν</g>, <r v=\"John.13.2\"></r> (cf. usage in <g>π.</g>, without idea of violence; also of liquids; MM, <i>Exp.</i>, x; v. also Cremer, 120, 657; cf. <g>ἀμφι-</g>, <g>ἀνα-</g>, <g>ἀντι-</g>, <g>ἀπο-</g>, <g>δια-</g>, <g>ἐκ-</g>, <g>ἐμ-</g>, <g>παρ-εμ-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>μετα-</g>, <g>παρα-</g>, <g>περι-</g>, <g>προ-</g>, <g>συμ-</g>, <g>ὑπερ-</g>, <g>ὑπο-βάλλω</g>).</s>"},"G901":{"l":"βαθύς","o":4,"ar":"<f><o>βαθύς</o> (حالة الجر <g>-έως</g>، في اللغة الدارجة، <r v=\"Luke.24.1\"></r>)، <g>-εῖα, -ύ</g>،</f> <s><b>عميق</b>؛ <r v=\"John.4.11\"></r>؛ مجازيًا، <g>ὄρθρου βαθέως</g> (انظر أعلاه)، <b>الفجر الباكر جدًّا</b>، <r v=\"Luke.24.1\"></r>؛ <g>ὕπνος</g>، <r v=\"Acts.20.9\"></r>؛ <g>τὰ β. τοῦ Σατανᾶ</g>، <r v=\"Rev.2.24\"></r>.†</s>","en":"<f><o>βαθύς</o> (gen. <g>-έως</g>, vernac., <r v=\"Luke.24.1\"></r>; Bl., § 8, 5), <g>-εῖα, -ύ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6009\">עמק</h>;]</e> </et> <s><b>deep</b>; <r v=\"John.4.11\"></r>; metaph., <g>ὄρθρου βαθέως</g> (v. supr.), <b>early dawn</b>, <r v=\"Luke.24.1\"></r>; <g>ὕπνος</g>, <r v=\"Acts.20.9\"></r>; <g>τὰ β. τοῦ Σατανᾶ</g>, <r v=\"Rev.2.24\"></r>.†</s>"},"G974":{"l":"βιβλαρίδιον","o":3,"ar":"<f>*† <o>βιβλαρίδιον</o>، <g>-ου, τό</g></f> <s><b>كتاب صغير، سِفر صغير</b>: <r v=\"Rev.10.2\"></r>، <r v=\"Rev.10.8\"></r>، <r v=\"Rev.10.9\"></r>، <r v=\"Rev.10.10\"></r>. لم يُعثر عليه حتى الآن في غير هذا الموضع.†</s>","en":"<f>*† <o>βιβλαρίδιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dim. of <x><g>βιβλάριον</g></x>, dim. of <x><g>βίβλος</g></x>),</e> </et> <s><b>a little book</b>: <r v=\"Rev.10.2\"></r>, <r v=\"Rev.10.8\"></r> (WH, <g>βιβλιόν</g>, T<i>2, 7</i> <g>βιβλιδάριον</g>) <r v=\"Rev.10.9\"></r>, <r v=\"Rev.10.10\"></r>. Not hitherto found elsewhere.†</s>"},"G980":{"l":"βιόω","o":1,"ar":"<f><o>βιόω</o>، <g>-ῶ</g> </f> <s><b>قضى حياته، عاش</b>: <g>τ. χρόνον βιῶσαι</g>، <r v=\"1Pet.4.2\"></r>.† </s>","en":"<f><o>βιόω</o>, <g>-ῶ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βίος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.7.2\"></r> <r v=\"Prov.9.6\"></r> (<h n=\"H2421\">חיה</h>), <r v=\"Job.29.18\"></r>, <r v=\"Wis.4.4\"></r> <h>א</h><i>1</i>, <r v=\"Wis.12.23\"></r>, <r v=\"Sir.40.28\"></r>, <r v=\"4Macc.5.22\"></r> <r v=\"4Macc.17.18\"></r> * ;]</e> </et> <s><b>to spend life, to live</b>: <g>τ. χρόνον βιῶσαι</g> (cl., more freq. 2 aor., <g>-ναι</g>), <r v=\"1Pet.4.2\"></r> (cf. Jb, l.c.).† </s> <sy><i>SYN.</i>: <g>ζάω</g> (q.v.).</sy>"},"G903":{"l":"Βαλαάμ","o":3,"ar":"<f><o>Βαλαάμ</o>، <g>ὁ</g>، لا يُصرَّف.</f> <s><b>بلعام</b> (<r v=\"Num.22.1-Num.24.25\"></r>): <r v=\"2Pet.2.15\"></r>، <r v=\"Jude.1.11\"></r>، <r v=\"Rev.2.14\"></r>.†</s>","en":"<f><o>Βαλαάμ</o>, <g>ὁ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1109\">בִּלְעָם</h>), as in LXX (FlJ has <g>ὁ βάλαμος</g>);</e> </et> <s><b>Balaam</b> (<r v=\"Num.22.1-Num.24.25\"></r>): <r v=\"2Pet.2.15\"></r>, <r v=\"Jude.1.11\"></r>, <r v=\"Rev.2.14\"></r>.†</s>"},"G978":{"l":"Βιθυνία","o":2,"ar":"<f><o>Βιθυνία</o>، <g>-ας</g>،</f> <s><b>بيثينية</b>، ولاية في آسيا الصغرى: <r v=\"Acts.16.7\"></r>، <r v=\"1Pet.1.1\"></r>.†</s>","en":"<f><o>Βιθυνία</o>, <g>-ας</g>,</f> <s><b>Bithynia</b>, a province in Asia Minor: <r v=\"Acts.16.7\"></r>, <r v=\"1Pet.1.1\"></r>.†</s>"},"G944":{"l":"βάτραχος","o":1,"ar":"<f><o>βάτραχος</o>، <g>-ου, ὁ</g>، </f> <s><b>ضفدع</b>: <r v=\"Rev.16.13\"></r>.†</s>","en":"<f><o>βάτραχος</o>, <g>-ου, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX: Ex 8, <r v=\"Ps.78.45\"></r> <r v=\"Ps.105.30\"></r> (<h n=\"???\">צְכַרִדֵּעַ</h><i>misspelling of צְפַרְדֵּעַ n=\"H6854\"</i>), <r v=\"Wis.19.10\"></r>*;]</e> </et> <s><b>a frog</b>: <r v=\"Rev.16.13\"></r>.†</s>"},"G995":{"l":"βοή","o":1,"ar":"<f><o>βοή</o>، <g>-ῆς, ἡ</g>، </f> <s><b>صياح، صراخ</b>: <r v=\"Jas.5.4\"></r>.†</s>","en":"<f><o>βοή</o>, <g>-ῆς, ἡ</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2201\">זְעָקָה</h>, etc. ;]</e> </et> <s><b>a cry</b>: <r v=\"Jas.5.4\"></r>.†</s>"},"G998":{"l":"βοηθός","o":1,"ar":"<f><o>βοηθός</o>، <g>-ον</g> (انظر تحت مدخل <g>βοηθέω</g>)، </f> <s> <s n=\"1.\">في اليونانية الكلاسيكية (وفي الشعر <g>-όος</g>): <b>مسرع إلى صيحة الحرب</b>. </s> <s n=\"2.\"><b>مُعين، مساعد</b>؛ اسمًا: <b>مُعين</b>: <r v=\"Heb.13.6\"></r> <i>(السبعينية)</i>.†</s> </s>","en":"<f><o>βοηθός</o>, <g>-ον</g> (v.s. <g>βοηθέω</g>), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5826\">עזר</h> ;]</e> </et> <s> <s n=\"1.\">(poët. <g>-όος</g>), <b>hasting to the war-cry</b> (Hom.). </s> <s n=\"2.\"><b>helping, auxiliary</b>; as subst. (Hdt.), <b>a helper</b>: <r v=\"Heb.13.6\"></r> <i>(LXX)</i>.†</s> </s>"},"G985":{"l":"βλαστάνω","o":4,"ar":"<f><o>βλαστάνω</o>، </f> <s> <s n=\"1.\"><b>يُفرِخ، ينبت</b>: <r v=\"Matt.13.26\"></r>، <r v=\"Mark.4.27\"></r>، <r v=\"Heb.9.4\"></r>. </s> <s n=\"2.\">في اليونانية المتأخرة متعدّيًا: <b>يُنبِت، يُخرِج</b>: مع المنصوب، <r v=\"Jas.5.18\"></r>.†</s> </s>","en":"<f><o>βλαστάνω</o>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6779\">צמח</h>, etc.;]</e> </et> <s> <s n=\"1.\"><b>to sprout</b>: <r v=\"Matt.13.26\"></r>, <r v=\"Mark.4.27\"></r>, <r v=\"Heb.9.4\"></r>. </s> <s n=\"2.\">In late Gk., causal, <b>to make to grow, produce</b>: c. acc., <r v=\"Jas.5.18\"></r>.†</s> </s>"},"G969":{"l":"βήρυλλος","o":1,"ar":"<f>**† <o>βήρυλλος</o>، <g>-ου, ὁ, ἡ</g>،</f> <s><b>زبرجد</b>، حجر كريم بلون أخضر بحري: <r v=\"Rev.21.20\"></r>.†</s>","en":"<f>**† <o>βήρυλλος</o>, <g>-ου, ὁ, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.13.17\"></r> (<g>-ύλλιον</g> in <r v=\"Exod.28.20\"></r>, <h n=\"H7718\">שֹׁהַם</h>)*;]</e> </et> <s><b>beryl</b>, a jewel of sea-green colour: <r v=\"Rev.21.20\"></r>.†</s>"},"G942":{"l":"βάτος","o":5,"ar":"<f><o>βάτος</o>، <g>-ου, ὁ, ἡ</g>،</f> <s><b>عُلَّيقة</b>: <r v=\"Luke.6.44\"></r>، <r v=\"Acts.7.30\"></r>، <r v=\"Acts.7.35\"></r>؛ <g>ἐπὶ τοῦ (τῆς) β.</g>، <b>في الموضع الخاص بالعُلَّيقة</b>: <r v=\"Mark.12.26\"></r>، <r v=\"Luke.20.37\"></r>.†</s>","en":"<f><o>βάτος</o>, <g>-ου, ὁ, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX (always masc, as in Attic): <r v=\"Exod.3.2-Exod.3.4\"></r>, <r v=\"Deut.33.16\"></r> (<h n=\"H5572\">סְנֶה</h>), <r v=\"Job.31.40\"></r> (<h n=\"H890\">בָּאְשָׁה</h>)*;]</e> </et> <s><b>a bramble-bush</b>: <r v=\"Luke.6.44\"></r>, <r v=\"Acts.7.30\"></r>, <r v=\"Acts.7.35\"></r>; <g>ἐπὶ τοῦ (τῆς) β.</g>, <b>in the place concerning the bush</b>: <r v=\"Mark.12.26\"></r>, <r v=\"Luke.20.37\"></r>.†</s>"},"G919":{"l":"Βαριησοῦς","o":1,"ar":"<f><o>Βαρ-ιησοῦς</o>، <g>-οῦ, ὁ</g></f> <s><b>باريشوع</b>: <r v=\"Acts.13.6\"></r> (انظر تحت مدخل <x><g>Ἐλύμας</g></x>).†</s>","en":"<f><o>Βαρ-ιησοῦς</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(Aram. <h n=\"H1247,H3343\">בַּר־יֵשׁוּעַ</h>, <i>son of Joshua</i>),</e> </et> <s><b>Bar-Jesus</b>: <r v=\"Acts.13.6\"></r> (v.s. <x><g>Ἐλύμας</g></x>).†</s>"},"G953":{"l":"βεβηλόω","o":2,"ar":"<f>† <o>βεβηλόω</o>، <g>-ῶ</g></f> <s><b>دنّس</b>: <g>τ. σάββατον</g>، <r v=\"Matt.12.5\"></r>؛ <g>τ. ἱερόν</g>، <r v=\"Acts.24.6\"></r>.†</s>","en":"<f>† <o>βεβηλόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βέβηλος</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2490\">חלל</h>;]</e> </et> <s><b>to profane</b>: <g>τ. σάββατον</g>, <r v=\"Matt.12.5\"></r>; <g>τ. ἱερόν</g>, <r v=\"Acts.24.6\"></r> (Cremer, 141).†</s> <sy><i>SYN.</i>: <x><g>κοινόω</g></x>, q.v.</sy>"},"G967":{"l":"Βηθφαγή","o":3,"ar":"<f><o>Βηθφαγή</o>، <g>ἡ</g>، لا يُصرَّف</f> <s><b>بيت فاجي</b>: <r v=\"Matt.21.1\"></r>، <r v=\"Mark.11.1\"></r>، <r v=\"Luke.19.29\"></r>.†</s>","en":"<f><o>Βηθφαγή</o> (L, <g>-γῆ</g>), <g>ἡ</g>, indecl.</f> <et> <e t=\"derivation\">(Aram. <h n=\"H1005\">בֵּית־פַּגֵּי</h>, <i>house of unripe figs</i>; Dalman, <i>Gr.</i>, 191),</e> </et> <s><b>Bethphage</b>: <r v=\"Matt.21.1\"></r>, <r v=\"Mark.11.1\"></r>, <r v=\"Luke.19.29\"></r>.†</s>"},"G920":{"l":"Βαριωνᾶς","o":1,"ar":"<f><o>Βαριωνᾶς</o>، <g>-ᾶ, ὁ</g></f> <s><b>باريونا</b>، لقب لبطرس: <r v=\"Matt.16.17\"></r>.†</s>","en":"<f><o>Βαριωνᾶς</o>, <g>-ᾶ, ὁ</g></f> <et> <e t=\"derivation\">(Aram. <h n=\"H1247,H3124\">בַּר־יוֹנָה</h>, <i>son of Jonah</i>),</e> </et> <s><b>Bar-Jonah</b>, a surname of Peter: <r v=\"Matt.16.17\"></r>.†</s>"},"G970":{"l":"βία","o":3,"ar":"<f><o>βία</o>، <g>-ας, ἡ</g></f> <s><b>قوة</b>، <b>قسر</b>، <b>عنف</b>: <r v=\"Acts.5.26\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.24.7\"></r> <r v=\"Acts.27.41\"></r>.†</s>","en":"<f><o>βία</o>, <g>-ας, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6531\">פֶּרֶךְ</h>, etc.;]</e> </et> <s><b>strength</b>, <b>force</b>, <b>violence</b>: <r v=\"Acts.5.26\"></r> <r v=\"Acts.21.35\"></r> <r v=\"Acts.24.7\"></r> <r v=\"Acts.27.41\"></r>.†</s>"},"G964":{"l":"Βηθεσδά","o":1,"ar":"<f><o>Βηθεσδά</o>، <g>ἡ</g>، لا يُصرَّف</f> <s><b>بيت حسدا</b>، بركة في أورشليم: <r v=\"John.5.2\"></r> (وفي قراءات أخرى <x><g>Βηθζαθά</g></x>، <x><g>Βηθσαϊδά</g></x>).†</s>","en":"<f><o>Βηθεσδά</o>, <g>ἡ</g>, indecl.</f> <et> <e t=\"derivation\">(deriv. uncertain, v. Westc. on <r v=\"John.5.2\"></r>, and <i>DB</i>, i, 279),</e> </et> <s><b>Bethesda</b>, a pool in Jerusalem: <r v=\"John.5.2\"></r>, Rec. (<x><g>Βηθζαθά</g></x>, WH, <x><g>Βηθσαϊδά</g></x>, WH, mg.).†</s>"},"G961":{"l":"Βεροιαῖος","o":1,"ar":"<f><o>Βεροιαῖος</o>، <g>-α, -ον</g>،</f> <s><b>بيري</b> (من بيرية): <r v=\"Acts.20.4\"></r>.†</s>","en":"<f><o>Βεροιαῖος</o>, <g>-α, -ον</g>,</f> <s><b>Berœan</b>: <r v=\"Acts.20.4\"></r>.†</s>"},"G971":{"l":"βιάζω","o":2,"ar":"<f><o>βιάζω</o> (مشتقة من <x><g>βία</g></x>)، وفعل لازم الصيغة الوسطى <g>-ομαι</g>،</f> <s><b>أجبر</b>، <b>أرغم</b>، نادر في المبني للمعلوم، لكنه يرد في الكلاسيكية في المبني للمجهول، وهكذا ربما <g>βιάζεται</g>، <b>يُغصَب</b>، <r v=\"Matt.11.12\"></r>، سواء <s n=\"(a)\">بمعنى حسن، عن التلاميذ، أو</s> <s n=\"(b)\">بمعنى سيئ، عن أعداء الملكوت. الصيغة الوسطى، <b>يتقدّم بعنف</b>، <r v=\"Matt.11.12\"></r>؛ يليه <g>εἰς</g>، <b>يندفع بعنف</b> أو <b>يشق طريقه بالقوة إلى</b>، <r v=\"Luke.16.16\"></r> (قارن <r v=\"Matt.11.12\"></r>؛ وقارن <x><g>παραβιάζομαι</g></x>).†</s> </s>","en":"<f><o>βιάζω</o> (&lt; <x><g>βία</g></x>), and depon. <g>-ομαι</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6555\">פּרץ</h>, <h n=\"H6484\">פּצר</h>, etc.;]</e> </et> <s><b>to force</b>, <b>constrain</b>, rare in act. (poet, and late prose), but found in cl. in pass., and so perh. <g>βιάζεται</g>, <b>suffereth violence</b>, <r v=\"Matt.11.12\"></r>, EV (but v. infr.), whether <s n=\"(a)\">in good sense, of disciples (Thayer, al.), or</s> <s n=\"(b)\">in bad sense, of the enemies of the kingdom (Meyer, in l.; Dalman, <i>Words</i>, 139 ff.; Cremer, 141 ff.). Mid., <b>advanceth violently</b>, <r v=\"Matt.11.12\"></r> (Deiss., <i>BS</i>., 258; Banks, v. ref. in <i>DCG</i>, ii, 803 f.); seq. <g>εἰς</g>, <b>to press violently</b>, or <b>force one's way into</b>, <r v=\"Luke.16.16\"></r> (v. <i>ICC</i>, in l., and in <r v=\"Matt.11.12\"></r>; cf. <x><g>παραβιάζομαι</g></x> and v. MM, s.v.).†</s> </s>"},"G910":{"l":"βαπτιστής","o":12,"ar":"<f>*† <o>βαπτιστής</o>، <g>-ου, ὁ</g></f> <s><b>معمِّد</b>: عن يوحنا المعمدان، <r v=\"Matt.3.1\"></r>، <r v=\"Matt.11.11\"></r>، <r v=\"Matt.11.12\"></r>، <r v=\"Matt.14.2\"></r>، <r v=\"Matt.14.8\"></r>، <r v=\"Matt.16.14\"></r>، <r v=\"Matt.17.13\"></r>، <r v=\"Mark.6.25\"></r>، <r v=\"Mark.8.28\"></r>، <r v=\"Luke.7.20\"></r>، <r v=\"Luke.7.33\"></r>، <r v=\"Luke.9.19\"></r>.†</s>","en":"<f>*† <o>βαπτιστής</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαπτίζω</g></x>),</e> </et> <s><b>a baptizer</b>: of John the Baptist, <r v=\"Matt.3.1\"></r> <r v=\"Matt.11.11\"></r>, <r v=\"Matt.11.12\"></r> <r v=\"Matt.14.2\"></r>, <r v=\"Matt.14.8\"></r> <r v=\"Matt.16.14\"></r> <r v=\"Matt.17.13\"></r>, <r v=\"Mark.6.25\"></r> <r v=\"Mark.8.28\"></r>, <r v=\"Luke.7.20\"></r>, <r v=\"Luke.7.33\"></r> <r v=\"Luke.9.19\"></r>.†</s>"},"G931":{"l":"βάσανος","o":3,"ar":"<f><o>βάσανος</o>، <g>-ου, ὁ</g> (من أصل شرقي)،</f> <s n=\"1.\">أصلاً: <b>حجر المِحَكّ</b>، حجر داكن يُستعمل في اختبار المعادن.</s> <s n=\"2.\"><b>استجواب بالتعذيب</b>.</s> <s n=\"3.\"><b>عذاب</b>، <b>تعذيب</b>: <r v=\"Matt.4.24\"></r>، <r v=\"Luke.15.23\"></r>، <r v=\"Luke.15.28\"></r>.†</s>","en":"<f><o>βάσανος</o>, <g>-ου, ὁ</g> (of Oriental origin),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3639,H817\">כְּלִמָּה ,אָשָׁם</h>, and freq. in IV Mac ;]</e> </et> <s n=\"1.\">prop., <b>touchstone</b>, a dark stone used in testing metals.</s> <s n=\"2.\"><b>examination by torture</b>.</s> <s n=\"3.\"><b>torment</b>, <b>torture</b>: <r v=\"Matt.4.24\"></r>, <r v=\"Luke.15.23\"></r>, <r v=\"Luke.15.28\"></r>.†</s>"},"G965":{"l":"Βηθλέεμ","o":8,"ar":"<f><o>Βηθλέεμ</o>، <g>ἡ</g>، لا يُصرَّف</f> <s><b>بيت لحم</b>، بلدة على بعد 6 أميال جنوب أورشليم: <r v=\"Matt.2.1\"></r>، <r v=\"Matt.2.5\"></r>، <r v=\"Matt.2.6\"></r>، <r v=\"Matt.2.8\"></r>، <r v=\"Matt.2.16\"></r>، <r v=\"Luke.2.4\"></r>، <r v=\"Luke.2.15\"></r>، <r v=\"John.7.42\"></r>.†</s>","en":"<f><o>Βηθλέεμ</o>, <g>ἡ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1004,H3899\">בֵּית לֶחֶם</h>, <i>house of bread</i>),</e> </et> <s><b>Bethlehem</b>, a town 6 m. S. of Jerusalem: <r v=\"Matt.2.1\"></r>, <r v=\"Matt.2.5\"></r>, <r v=\"Matt.2.6\"></r>, <r v=\"Matt.2.8\"></r>, <r v=\"Matt.2.16\"></r>, <r v=\"Luke.2.4\"></r>, <r v=\"Luke.2.15\"></r>, <r v=\"John.7.42\"></r>.†</s>"},"G973":{"l":"βιαστής","o":1,"ar":"<f>*† <o>βιαστής</o>، <g>-οῦ, ὁ</g> (مشتقة من <x><g>βιάζω</g></x>)، صيغة متأخرة من <x><g>βιατάς</g></x>؛</f> <s n=\"1.\"><b>قوي</b>، <b>عنيف القوة</b>.</s> <s n=\"2.\"><b>عنيف، غاصب</b>: <r v=\"Matt.11.12\"></r> (انظر تحت مدخل <x><g>βιάζω</g></x>).†</s>","en":"<f>*† <o>βιαστής</o>, <g>-οῦ, ὁ</g> (&lt; <x><g>βιάζω</g></x>), late form of <x><g>βιατάς</g></x>;</f> <s n=\"1.\"><b>strong</b>, <b>forceful</b>.</s> <s n=\"2.\"><b>violent</b> (Philo): <r v=\"Matt.11.12\"></r> (v.s. <x><g>βιάζω</g></x>).†</s>"},"G930":{"l":"βασανιστής","o":1,"ar":"<f>* <o>βασανιστής</o>، <g>-οῦ, ὁ</g></f> <s>أصلاً، <b>معذِّب</b>؛ يُستعمل عن السجّان، <r v=\"Matt.18.34\"></r>.†</s>","en":"<f>* <o>βασανιστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βασανίζω</g></x>),</e> </et> <s>prop., <b>a torturer</b>; used of a gaoler, <r v=\"Matt.18.34\"></r>.†</s>"},"G914":{"l":"Βαραχίας","o":1,"ar":"<f><o>Βαραχίας</o>، <g>-ου, ὁ</g></f> <s><b>برخيا</b>: <r v=\"Matt.23.35\"></r>، انظر تحت مدخل <x><g>Ζαχαρίας</g></x>.†</s>","en":"<f><o>Βαραχίας</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(Heb. <h n=\"H1296\">בֶּרֶכְיָה</h>),</e> </et> <s><b>Barachiah</b>: <r v=\"Matt.23.35\"></r>, v.s. <x><g>Ζαχαρίας</g></x>.†</s>"},"G972":{"l":"βίαιος","o":1,"ar":"<f><o>βίαιος</o>، <g>-α, -ον</g></f> <s><b>عنيف، عاصف</b>: <r v=\"Acts.2.2\"></r>.†</s>","en":"<f><o>βίαιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βία</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H605\">אָנַשׁ</h>, <h n=\"H5794\">עַז</h>, <h n=\"H6862\">צַר</h>, etc.;]</e> </et> <s><b>violent</b>: <r v=\"Acts.2.2\"></r>.†</s>"},"G966":{"l":"Βηθσαϊδά","o":5,"ar":"<f><o>Βηθσαιδά</o>، و<g>-δάν</g> (<r v=\"Matt.11.21\"></r>، <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.22\"></r>)، <g>ἡ</g>، لا يُصرَّف</f> <s><b>بيت صيدا</b>، بلدة على الشاطئ الشمالي الشرقي لبحر الجليل: <r v=\"Luke.9.10\"></r>. ويُفترض عمومًا أن <g>Β.</g> ثانية على الشاطئ الغربي هي المقصودة في <r v=\"Matt.11.21\"></r>، <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.22\"></r>، <r v=\"Luke.10.13\"></r>، <r v=\"John.1.45\"></r> <r v=\"John.12.21\"></r> (وقارن <r v=\"Mark.6.45\"></r>). <s n=\"2.\">قراءة بديلة عن <x><g>Βηθζαθά</g></x>، <x><g>Βηθεσδά</g></x>، <r v=\"John.5.2\"></r>.†</s> </s>","en":"<f><o>Βηθσαιδά</o> (Rec. <g>-σαϊδά</g>), and <g>-δάν</g> (<r v=\"Matt.11.21\"></r>, <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.22\"></r>), <g>ἡ</g>, indecl.</f> <et> <e t=\"derivation\">(Syr., <i>house of fish</i>),</e> </et> <s><b>Bethsaida</b>, a town on NE. shore of the Sea of Galilee: <r v=\"Luke.9.10\"></r>. It is generally supposed that a second <g>Β.</g> on the W. shore is referred to in <r v=\"Matt.11.21\"></r>, <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.22\"></r>, <r v=\"Luke.10.13\"></r>, <r v=\"John.1.45\"></r> <r v=\"John.12.21\"></r> (<i>DB</i>, i, 282 f.; but v. Swete on <r v=\"Mark.6.45\"></r>). <s n=\"2.\">v.l. for <x><g>Βηθζαθά</g></x>, <x><g>Βηθεσδά</g></x>, <r v=\"John.5.2\"></r>.†</s> </s>"},"G945":{"l":"βατταλογέω","o":1,"ar":"<f>*† <o>βατταλογέω</o>، <g>-ῶ</g> (= <g>βατταρίζω</g>، وربما هي محاكاة صوتية)؛</f> <s><b>تلعثم</b>، <b>كرّر الكلام باطلاً</b>: <r v=\"Matt.6.7\"></r>.†</s>","en":"<f>*† <o>βατταλογέω</o>, <g>-ῶ</g> (Rec. <g>βαττολ-</g>, D, <g>βλαττ-</g> = <g>βατταρίζω</g>, prob. onomatop.; v. MM, s.v.; <i>DCG</i>, ii, 499<i>b</i>, 790<i>a</i>);</f> <s><b>to stammer</b>, <b>repeat idly</b>: <r v=\"Matt.6.7\"></r> (Cremer, 765).†</s>"},"G999":{"l":"βόθυνος","o":3,"ar":"<f><o>βόθυνος</o>، <g>-ου, ὁ</g> (= <g>βόθρος</g>، الأكثر شيوعًا في الكلاسيكية)، </f> <s><b>حفرة</b>: <r v=\"Matt.12.11\"></r> <r v=\"Matt.15.14\"></r>، <r v=\"Luke.6.39\"></r>.†</s>","en":"<f><o>βόθυνος</o>, <g>-ου, ὁ</g> (= <g>βόθρος</g>, more freq. in cl.), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6354\">פַּחַת</h> ;]</e> </et> <s><b>a pit</b>: <r v=\"Matt.12.11\"></r> <r v=\"Matt.15.14\"></r>, <r v=\"Luke.6.39\"></r> (cf. <i>DB</i>, iii, 885; <i>DCG</i>, ii, 367).†</s>"},"G959":{"l":"Βερνίκη","o":3,"ar":"<f><o>Βερνίκη</o></f> <s><b>برنيكي</b>، ابنة هيرودس أغريباس الأول: <r v=\"Acts.25.13\"></r>، <r v=\"Acts.25.23\"></r> <r v=\"Acts.26.30\"></r>.†</s>","en":"<f><o>Βερνίκη</o></f> <et> <e t=\"derivation\">(elsewhere <x><g>Βερενίκη</g></x>, Macedonian form of <g>Φερενίκη</g>, cf. <i>Veronica</i>, <i>Victoria</i>), <g>-ης, ἡ</g>,</e> </et> <s><b>Bernice</b>, <b>Berenice</b>, dau. of Herod Agrippa I: <r v=\"Acts.25.13\"></r>, <r v=\"Acts.25.23\"></r> <r v=\"Acts.26.30\"></r>.†</s>"},"G927":{"l":"βαρύτιμος","o":1,"ar":"<f>* <o>βαρύτιμος</o>، <g>-ον</g></f> <s><b>عظيم القيمة</b>، <b>كثير الثمن جدًا</b>: <r v=\"Matt.26.7\"></r>.†</s>","en":"<f>* <o>βαρύτιμος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαρύς</g></x>, <x><g>τιμή</g></x>),</e> </et> <s><b>of great value</b>, <b>very costly</b>: <r v=\"Matt.26.7\"></r> (T, <g>πολυτίμου</g>).†</s>"},"G923":{"l":"Βαρσαββᾶς","o":2,"ar":"<f><o>Βαρσαββᾶς</o>، <g>-ᾶ</g></f> <s><b>برسابا</b>: <s n=\"1.\">لقب رجل اسمه يوسف: <r v=\"Acts.1.23\"></r>.</s> <s n=\"2.\">لقب رجل اسمه يهوذا: <r v=\"Acts.15.22\"></r>.†</s> </s>","en":"<f><o>Βαρσαββᾶς</o> (Rec. <g>-αβᾶς</g>), <g>-ᾶ</g></f> <et> <e t=\"derivation\">(Aram., <i>son of Sabba</i>),</e> </et> <s><b>Barsabbas</b>: <s n=\"1.\">the surname of one Joseph: <r v=\"Acts.1.23\"></r>.</s> <s n=\"2.\">The surname of one Judas: <r v=\"Acts.15.22\"></r>.†</s> </s>"},"G918":{"l":"Βαρθολομαῖος","o":4,"ar":"<f><o>Βαρθολομαῖος</o>، <g>-ου, ὁ</g></f> <s><b>برثولماوس</b>، الرسول (انظر تحت مدخل <x><g>Ναθαναήλ</g></x>): <r v=\"Matt.10.3\"></r>، <r v=\"Mark.3.18\"></r>، <r v=\"Luke.6.14\"></r>، <r v=\"Acts.1.13\"></r>.†</s>","en":"<f><o>Βαρθολομαῖος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(Aram. <h n=\"H1247,H8526\">בַּר־תָּלְמַי</h>, <i>son of Tolmai</i>),</e> </et> <s><b>Bartholomew</b>, the Apostle (v.s. <x><g>Ναθαναήλ</g></x>): <r v=\"Matt.10.3\"></r>, <r v=\"Mark.3.18\"></r>, <r v=\"Luke.6.14\"></r>, <r v=\"Acts.1.13\"></r>.†</s>"},"G905":{"l":"βαλλάντιον","o":4,"ar":"<f><o>βαλλάντιον</o>، <g>-ου, ὁ</g>،</f> <s><b>كيس (للنقود)</b>: <r v=\"Luke.10.4\"></r> <r v=\"Luke.12.33\"></r> <r v=\"Luke.22.35\"></r>، <r v=\"Luke.22.36\"></r>.†</s>","en":"<f><o>βαλλάντιον</o> (Rec. <g>βαλά-</g>), <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.14.17\"></r> (<h n=\"H6872\">צְרוֹר</h>), <r v=\"Prov.1.14\"></r> (<h n=\"H3599\">כִּיס</h>), <r v=\"Tob.1.14\"></r> <r v=\"Tob.8.2\"></r>, <r v=\"Sir.18.33\"></r> <h>א</h><i>2</i>*;]</e> </et> <s><b>a purse</b>: <r v=\"Luke.10.4\"></r> <r v=\"Luke.12.33\"></r> <r v=\"Luke.22.35\"></r>, <r v=\"Luke.22.36\"></r>.†</s>"},"G917":{"l":"βαρέως","o":2,"ar":"<f><o>βαρέως</o>، ظرف</f> <s><b>بثقل</b>، <b>بصعوبة</b>: <r v=\"Matt.13.15\"></r>، <r v=\"Acts.28.27\"></r> (السبعينية).†</s>","en":"<f><o>βαρέως</o>, adv.</f> <et> <e t=\"derivation\">(&lt; <x><g>βαρύς</g></x>),</e> <e t=\"septuagint\">[in LXX: <g>β. φέρειν</g>, <r v=\"Gen.31.35\"></r> (<h n=\"H5869,H2763\">בעיני חרה</h>); <g>β. ἀκούειν</g>, <r v=\"Isa.6.10\"></r> (<h n=\"H3513\">כּבד</h> hi.)*;]</e> </et> <s><b>heavily</b>, <b>with difficulty</b>: <r v=\"Matt.13.15\"></r>, <r v=\"Acts.28.27\"></r> (LXX).†</s>"},"G954":{"l":"Βεελζεβούλ","o":7,"ar":"<f><o>Βεελζεβούλ</o> (ويُكتب أيضًا <x><g>βεελζεβούλ</g></x>)، <g>ὁ</g>، لا يُصرَّف</f> <s><b>بعلزبول</b>، <b>بعلزبوب</b>، اسم للشيطان: <r v=\"Matt.10.25\"></r> <r v=\"Matt.12.24\"></r>، <r v=\"Matt.12.27\"></r>، <r v=\"Mark.3.22\"></r>، <r v=\"Luke.11.15\"></r>، <r v=\"Luke.11.18\"></r>، <r v=\"Luke.11.19\"></r>.†</s>","en":"<f><o>Βεελζεβούλ</o> (WH, <i>App.</i>, 159, Rec., <x><g>βεελζεβούλ</g></x>), <g>ὁ</g>, indecl.</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1167\">בַּעַל</h>, <i>lord</i>, and the Talmudic <h n=\"H2073\">זִבּוּל</h>, from <h n=\"????\">זֶבֶל</h>, <i>dung</i> (Dalman, <i>Gr.</i>, 137<i>n</i>), or perh. <h n=\"H2083\">זְבֻל</h>, <i>habitation</i>, but, v. <i>DB</i>, iv, 409 f.; <i>DCG</i>, i, 181). The AV, RV, <i>Beelzebub</i>, comes through Vg. from <r v=\"2Kgs.1.2\"></r>, <h n=\"H1167,H2073\">בַּעַל זִבוּב</h>, <i>lord of flies</i></e> <e t=\"septuagint\">(LXX, <g>βάαλ μυῖα</g>, Sm., <g>βεελζεβούβ</g>),</e> </et> <s><b>Beelzebul</b>, <b>Beelzebub</b>, a name of Satan: <r v=\"Matt.10.25\"></r> <r v=\"Matt.12.24\"></r>, <r v=\"Matt.12.27\"></r>, <r v=\"Mark.3.22\"></r>, <r v=\"Luke.11.15\"></r>, <r v=\"Luke.11.18\"></r>, <r v=\"Luke.11.19\"></r>.†</s>"},"G992":{"l":"βλητέος","o":1,"ar":"<f>*† <o>βλητέος</o>، <g>-α, -ον</g> (صفة الوجوب من <g>βάλλω</g>)، </f> <s>(ما) <b>ينبغي أن يُوضع</b>: <r v=\"Luke.5.38\"></r>.†</s>","en":"<f>*† <o>βλητέος</o>, <g>-α, -ον</g> (gerundive of <g>βάλλω</g>), </f> <s>(that which) <b>one must put</b>: <r v=\"Luke.5.38\"></r>.†</s>"},"G960":{"l":"Βέροια","o":2,"ar":"<f><o>Βέροια</o>، <g>-ας, ἡ</g>،</f> <s><b>بيرية</b>، مدينة في مكدونية: <r v=\"Acts.17.10\"></r>، <r v=\"Acts.17.13\"></r>.†</s>","en":"<f><o>Βέροια</o>, <g>-ας, ἡ</g>,</f> <s><b>Berœa</b>, a city of Macedonia: <r v=\"Acts.17.10\"></r>, <r v=\"Acts.17.13\"></r>.†</s>"},"G986":{"l":"Βλάστος","o":1,"ar":"<f><o>Βλάστος</o>، <g>-ου, ὁ</g>، </f> <s><b>بلاستس</b>، الناظر على مخدع أغريباس: <r v=\"Acts.12.20\"></r>.†</s>","en":"<f><o>Βλάστος</o>, <g>-ου, ὁ</g>, </f> <s><b>Blastus</b>, chamberlain of Agrippa: <r v=\"Acts.12.20\"></r>.†</s>"},"G900":{"l":"βαθύνω","o":1,"ar":"<f><o>βαθύνω</o></f> <s><b>عمّق</b>: <r v=\"Luke.6.48\"></r>.†</s>","en":"<f><o>βαθύνω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>βαθύς</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H5975\">עמד</h>: <r v=\"Ps.92.5\"></r>, <r v=\"Jer.49.8\"></r> <r v=\"Jer.49.30\"></r>*;]</e> </et> <s><b>to deepen</b>: <r v=\"Luke.6.48\"></r>.†</s>"},"G963":{"l":"Βηθανία","o":12,"ar":"<f><o>Βηθανία</o>، <g>-ας</g> (وأيضًا <g>-ιά</g>، لا يُصرَّف، <r v=\"Luke.19.29\"></r>، <r v=\"Mark.11.1\"></r>)، <g>ἡ</g>،</f> <s><b>بيت عنيا</b>؛ <s n=\"1.\">قرية على بعد خمس عشرة غلوة من أورشليم، هي <i>العيزرية</i> الحالية: <r v=\"Matt.21.17\"></r> <r v=\"Matt.26.6\"></r>، <r v=\"Mark.8.22\"></r> <r v=\"Mark.11.1\"></r>، <r v=\"Mark.11.11\"></r>، <r v=\"Mark.11.12\"></r> <r v=\"Mark.14.3\"></r>، <r v=\"Luke.19.29\"></r> <r v=\"Luke.24.50\"></r>، <r v=\"John.11.1\"></r>، <r v=\"John.11.18\"></r> <r v=\"John.12.1\"></r>.</s> <s n=\"2.\">موضع على الضفة الشرقية للأردن: <r v=\"John.1.28\"></r>.†</s> </s>","en":"<f><o>Βηθανία</o>, <g>-ας</g> (also <g>-ιά</g>, indecl., <r v=\"Luke.19.29\"></r> and in B*, <r v=\"Mark.11.1\"></r>), <g>ἡ</g>,</f> <et> <e t=\"derivation\">(Heb. <h n=\"H1004,H6041\">בֵּית עֲנִיָּה</h>, <i>house of affliction</i>, acc. to Jerome, or perh., <i>house of dates</i>, cf. <i>Bethphage</i>),</e> </et> <s><b>Bethany</b>; <s n=\"1.\">a village fifteen furlongs from Jerusalem, the modern <i>El Azerîyeh</i>: <r v=\"Matt.21.17\"></r> <r v=\"Matt.26.6\"></r>, <r v=\"Mark.8.22\"></r> (WH, mg.) <r v=\"Mark.11.1\"></r>, <r v=\"Mark.11.11\"></r>, <r v=\"Mark.11.12\"></r> <r v=\"Mark.14.3\"></r>, <r v=\"Luke.19.29\"></r> <r v=\"Luke.24.50\"></r>, <r v=\"John.11.1\"></r>, <r v=\"John.11.18\"></r> <r v=\"John.12.1\"></r>.</s> <s n=\"2.\">A place on E. bank of Jordan: <r v=\"John.1.28\"></r> (R, mg., <x><g>Βηθαβαρά</g></x>, q.v.).†</s> </s>"},"G943":{"l":"βάτος_2","o":1,"ar":"<f>† <o>βάτος</o>، <g>-ου, ὁ</g></f> <s><b>بثّ</b>، مكيال يهودي للسوائل، = <g>μετρητής</g> (انظره)، أي نحو 8 3/4 غالونات: <r v=\"Luke.16.6\"></r>.†</s>","en":"<f>† <o>βάτος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(Heb. <h n=\"H1324\">בַּת</h>),</e> <e t=\"septuagint\">[in LXX (also <g>βαίθ</g>, <g>βάδος</g>): <r v=\"2Esd.7.22\"></r>*;]</e> </et> <s><b>bath</b>, a Jewish liquid measure, = <g>μετρητής</g> (q.v.), or about 8 3/4 gals.: <r v=\"Luke.16.6\"></r>.†</s>"},"G981":{"l":"βίωσις","o":1,"ar":"<f>**† <o>βίωσις</o>، <g>-εως, ἡ</g> </f> <s><b>سيرة، طريقة الحياة</b>: <r v=\"Acts.26.4\"></r>.†</s>","en":"<f>**† <o>βίωσις</o>, <g>-εως, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>βιόω</g>), </e> <e t=\"septuagint\">[in LXX: Si <i>prol.</i> <i>12</i> * ;]</e> </et> <s><b>manner of life</b>: <r v=\"Acts.26.4\"></r>.†</s>"},"G977":{"l":"βιβρώσκω","o":1,"ar":"<f><o>βιβρώσκω</o>، في الشعر وفي النثر المتأخر،</f> <s><b>أكل</b>: <r v=\"John.6.13\"></r>.†</s>","en":"<f><o>βιβρώσκω</o>, poët, and late prose,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H398\">אכל</h>;]</e> </et> <s><b>to eat</b>: <r v=\"John.6.13\"></r>.†</s>"},"G924":{"l":"Βαρτιμαῖος","o":1,"ar":"<f><o>Βαρτίμαιος</o>، <g>-ου, ὁ</g></f> <s><b>بارتيماوس</b>: <r v=\"Mark.10.46\"></r>.†</s>","en":"<f><o>Βαρτίμαιος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(<g>-μαῖος</g>, T; perh. Aram. <h n=\"H1247\">בַּר־טִמְאַי</h>, v. <i>DB</i>, iv, p. 762),</e> </et> <s><b>Bartimæus</b>: <r v=\"Mark.10.46\"></r>.†</s>"},"G912":{"l":"Βαραββᾶς","o":11,"ar":"<f><o>Βαραββᾶς</o>، <g>-ᾶ, ὁ</g></f> <s><b>باراباس</b>: <r v=\"Matt.27.16\"></r>، <r v=\"Matt.27.17\"></r>، <r v=\"Matt.27.20\"></r>، <r v=\"Matt.27.21\"></r>، <r v=\"Matt.27.26\"></r>، <r v=\"Mark.15.7\"></r>، <r v=\"Mark.15.11\"></r>، <r v=\"Mark.15.15\"></r>، <r v=\"Luke.23.18\"></r>، <r v=\"John.18.40\"></r>. (في <r v=\"Matt.27.16\"></r> تقرأ بعض المخطوطات <g>Ἰησοῦν Β.</g>).†</s>","en":"<f><o>Βαραββᾶς</o>, <g>-ᾶ, ὁ</g></f> <et> <e t=\"derivation\">(Aram. <h n=\"H1247,H2\">בַּר־אַבָּא</h>, lit., <i>son of a father</i>, i.e. acc. to Jerome, <l>filius magistri</l>),</e> </et> <s><b>Barabbas</b>: <r v=\"Matt.27.16\"></r>, <r v=\"Matt.27.17\"></r>, <r v=\"Matt.27.20\"></r>, <r v=\"Matt.27.21\"></r>, <r v=\"Matt.27.26\"></r>, <r v=\"Mark.15.7\"></r>, <r v=\"Mark.15.11\"></r>, <r v=\"Mark.15.15\"></r>, <r v=\"Luke.23.18\"></r>, <r v=\"John.18.40\"></r>. (In <r v=\"Matt.27.16\"></r>, some MSS. read <g>Ἰησοῦν Β.</g>; v. WH, <i>App.</i>, 19 f.).†</s>"},"G993":{"l":"Βοανηργές","o":1,"ar":"<f><o>Βοανηργές</o>، لا يُصرَّف، </f> <s><b>بوانرجس</b>: <r v=\"Mark.3.17\"></r>.†</s>","en":"<f><o>Βοανηργές</o>, indecl. (on the derivation, v. Dalman, <i>Gr.</i>, 144; <i>Words</i>, 42; Swete, <i>Mk.</i>, l.c.; <i>DCG</i>, i, 216), </f> <s><b>Boanerges</b>: <r v=\"Mark.3.17\"></r>.†</s>"},"G933":{"l":"βασίλειον","o":1,"ar":"<f><o>βασίλειον</o>، <g>-ου, τό</g></f> <s> <s n=\"1.\">مدينة <b>عاصمة</b>.</s> <s n=\"2.\">وكثيرًا في الجمع، <g>τὰ β.</g>، <b>قصر</b>: <r v=\"Luke.7.25\"></r>.†</s> </s>","en":"<f><o>βασίλειον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βασίλειος</g></x>, q.v.),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1964\">הֵיכָל</h> (<r v=\"Nah.2.6\"></r>, <r v=\"Dan.6.18\"></r>*), <h n=\"H4467\">מַמְלָכָה</h> (<r v=\"1Kgs.3.1\"></r> <r v=\"1Kgs.14.8\"></r>, <r v=\"2Kgs.15.19\"></r>*), etc.;]</e> </et> <s> <s n=\"1.\">a <b>capital</b> city.</s> <s n=\"2.\">Freq. in pl., <g>τὰ β.</g>, <b>a palace</b>: <r v=\"Luke.7.25\"></r>.†</s> </s>"},"G939":{"l":"βάσις","o":1,"ar":"<f><o>βάσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>خطوة</b>.</s> <s n=\"2.\">ومن ثم، <b>قدم</b> (قارن <r v=\"Wis.13.18\"></r>): <r v=\"Acts.3.7\"></r>.†</s>","en":"<f><o>βάσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>βαίνω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H134\">אֶדֶן</h>;]</e> </et> <s n=\"1.\"><b>a step</b> (Æsch., al.).</s> <s n=\"2.\">Hence, <b>a foot</b> (Plat.; <r v=\"Wis.13.18\"></r>): <r v=\"Acts.3.7\"></r>.†</s>"},"G984":{"l":"βλάπτω","o":2,"ar":"<f><o>βλάπτω</o>، </f> <s><b>أضرّ، آذى</b>: مع المنصوب، <r v=\"Mark.16.18\"></r>، <r v=\"Luke.4.35\"></r>.†</s>","en":"<f><o>βλάπτω</o>, </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.25.20\"></r>, <r v=\"Tob.12.2\"></r>, <r v=\"Wis.10.8\"></r> <r v=\"Wis.18.2\"></r>, <r v=\"2Macc.12.22\"></r>, <r v=\"4Macc.9.7\"></r>* ;]</e> </et> <s><b>to hurt, injure</b>: c. acc., <r v=\"Mark.16.18\"></r>, <r v=\"Luke.4.35\"></r>.†</s>"},"G902":{"l":"βαΐον","o":1,"ar":"<f>**† <o>βαΐον</o>، <g>ου, τό</g></f> <s>سعفة نخل: <r v=\"John.12.13\"></r>.†</s>","en":"<f>**† <o>βαΐον</o>, <g>ου, τό</g></f> <et> <e t=\"derivation\">(also <x><g>βὰϊον</g></x>, another form of <x><g>βὰϊς</g></x>, from the Egyptian), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.13.51\"></r>*;],</e> <e t=\"derivation\">(freq. in Egyptian <g>π.</g>, v. MM, <i>Exp.</i>, x);</e> </et> <s>a palm-branch: <r v=\"John.12.13\"></r> (<i>DB</i>, i, 314).†</s>"}});A.got[9]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});